RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION USING
    ERRCODE = 'ZA005',
    MESSAGE = pg_catalog.format('%I source/audit history is immutable', TG_TABLE_NAME),
    DETAIL = 'SOURCE_HISTORY_IMMUTABLE';
END;
$$;

