-- BEGIN COACH PUBLISH 2bb50cabc8b7ce0fd77c25c0800c35c17b4bfaa3419f7a140d70719ac2ba5847
-- schema.v1.19 coach product/campaign publish. runtime_activated remains false.
-- CREATE OR REPLACE of publish_content_release only. Rollback stays owner-only.
-- Coach may publish when every binding and staging row is product|campaign and
-- title/answer_text contain neither 过敏 nor 赔付. Aftersale and 过敏/赔付 stay owner.
CREATE OR REPLACE FUNCTION publish_content_release(
  p_import_batch_id TEXT,
  p_title TEXT,
  p_summary TEXT,
  p_actor_user_id TEXT,
  p_actor_role TEXT
) RETURNS TABLE(release_id TEXT, release_seq BIGINT, announcement_id TEXT, source_binding_hash TEXT)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  v_got BOOLEAN;
  v_release_id TEXT;
  v_seq BIGINT;
  v_ann TEXT;
  v_prev TEXT;
  v_base TEXT;
  v_expected_source_hash TEXT;
  v_source_hash TEXT;
  v_source_count INT;
  v_source_noncanonical BOOLEAN;
  v_source_suspended BOOLEAN;
  v_ok_count INT;
  v_publishable_upsert_count INT;
  v_quality_population_hash TEXT;
  v_batch_claimed INT;
BEGIN
  -- p_actor_role is a server-verified end-user claim used for policy/audit. DB ACL authenticates
  -- the isolated app_content_admin workload identity; the API must select that pool only after
  -- verified owner or in-scope coach authorization. The parameter itself is not independent database authentication.
  IF p_actor_user_id IS NULL OR pg_catalog.btrim(p_actor_user_id) = '' THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA005', MESSAGE = 'publish requires an actor', DETAIL = 'FORBIDDEN';
  END IF;
  IF p_actor_role = 'coach' THEN
    IF EXISTS (
      SELECT 1 FROM public.import_batch_source_bindings ib
      WHERE ib.import_batch_id = p_import_batch_id
        AND ib.domain NOT IN ('product', 'campaign')
    ) OR EXISTS (
      SELECT 1 FROM public.staging_scripts s
      WHERE s.import_batch_id = p_import_batch_id
        AND (
          s.category NOT IN ('product', 'campaign')
          OR coalesce(s.title, '') LIKE '%过敏%'
          OR coalesce(s.title, '') LIKE '%赔付%'
          OR coalesce(s.answer_text, '') LIKE '%过敏%'
          OR coalesce(s.answer_text, '') LIKE '%赔付%'
        )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = 'ZA005', MESSAGE = 'coach publish is limited to product and campaign without 过敏/赔付', DETAIL = 'FORBIDDEN';
    END IF;
  ELSIF p_actor_role IS DISTINCT FROM 'owner' THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA005', MESSAGE = 'publish requires owner or in-scope coach', DETAIL = 'FORBIDDEN';
  END IF;
  IF p_import_batch_id IS NULL OR pg_catalog.btrim(p_import_batch_id) = '' THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'import_batch_id is required', DETAIL = 'VALIDATION';
  END IF;

  v_got := pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtext('cs_ai_content_publish'));
  IF NOT v_got THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA003', MESSAGE = 'publish single-flight lock not acquired', DETAIL = 'CONFLICT';
  END IF;
  PERFORM pg_catalog.set_config('app.publishing', 'on', true);

  -- Atomic compare-and-set is the publish/cancel serialization point. If cancel wins first, this
  -- touches zero rows; if publish wins first, cancel waits on the row lock and then sees publishing.
  UPDATE public.import_batches
  SET status = 'publishing'
  WHERE import_batch_id = p_import_batch_id
    AND status = 'staged';
  GET DIAGNOSTICS v_batch_claimed = ROW_COUNT;
  IF v_batch_claimed <> 1 THEN
    IF NOT EXISTS (SELECT 1 FROM public.import_batches WHERE import_batch_id = p_import_batch_id) THEN
      RAISE EXCEPTION USING ERRCODE = 'ZA002', MESSAGE = 'import_batch does not exist', DETAIL = 'NOT_FOUND';
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'ZA003', MESSAGE = 'import_batch is not staged or is concurrently changing', DETAIL = 'CONFLICT';
  END IF;

  SELECT b.base_release_id, b.source_binding_hash
  INTO v_base, v_expected_source_hash
  FROM public.import_batches b
  WHERE b.import_batch_id = p_import_batch_id;

  SELECT c.current_release_id INTO v_prev
  FROM public.content_current c WHERE c.id = 1 FOR UPDATE;
  IF v_prev IS DISTINCT FROM v_base THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA003', MESSAGE = 'import was validated against a stale current release', DETAIL = 'SOURCE_BASE_RELEASE_STALE';
  END IF;

  WITH prospective AS (
    SELECT ib.domain, ib.source_version_id
    FROM public.import_batch_source_bindings ib
    WHERE ib.import_batch_id = p_import_batch_id
    UNION ALL
    SELECT rb.domain, rb.source_version_id
    FROM public.release_source_bindings rb
    WHERE rb.release_id = v_prev
      AND NOT EXISTS (
        SELECT 1 FROM public.import_batch_source_bindings ib
        WHERE ib.import_batch_id = p_import_batch_id AND ib.domain = rb.domain
      )
  )
  SELECT
    pg_catalog.count(*)::INT,
    pg_catalog.encode(public.digest(pg_catalog.convert_to(
      pg_catalog.string_agg(p.domain || ':' || p.source_version_id, '|' ORDER BY p.domain),
      'UTF8'
    ), 'sha256'), 'hex'),
    coalesce(pg_catalog.bool_or(asv.use_class <> 'canonical'), FALSE),
    coalesce(pg_catalog.bool_or(susp.source_version_id IS NOT NULL), FALSE)
  INTO v_source_count, v_source_hash, v_source_noncanonical, v_source_suspended
  FROM prospective p
  JOIN public.authoritative_source_versions asv
    ON asv.source_version_id = p.source_version_id AND asv.domain = p.domain
  LEFT JOIN public.authoritative_source_suspensions susp
    ON susp.source_version_id = p.source_version_id;

  IF v_source_count <> 4 THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'prospective release requires exactly four source domains', DETAIL = 'SOURCE_SET_INCOMPLETE';
  END IF;
  IF v_source_noncanonical THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA004', MESSAGE = 'prospective release contains a reference-only source', DETAIL = 'SOURCE_NOT_ELIGIBLE';
  END IF;
  IF v_source_suspended THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA004', MESSAGE = 'prospective release contains a suspended source', DETAIL = 'SOURCE_SUSPENDED';
  END IF;
  IF v_source_hash IS DISTINCT FROM v_expected_source_hash THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA003', MESSAGE = 'prospective source set changed after enqueue', DETAIL = 'SOURCE_BINDING_HASH_MISMATCH';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.staging_scripts s
    WHERE s.import_batch_id = p_import_batch_id AND s.validation_ok IS NOT TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'staging has invalid rows', DETAIL = 'VALIDATION';
  END IF;

  SELECT COUNT(*) INTO v_ok_count FROM public.staging_scripts s
  WHERE s.import_batch_id = p_import_batch_id
    AND s.validation_ok
    AND s.quality_status = 'clean'
    AND s.quality_gate_passed;
  IF v_ok_count IS NULL OR v_ok_count < 1 THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'no clean content passed the quality gate', DETAIL = 'QUALITY_GATE_NOT_PASSED';
  END IF;
  SELECT pg_catalog.count(*)::INT INTO v_publishable_upsert_count
  FROM public.staging_scripts s
  WHERE s.import_batch_id = p_import_batch_id
    AND s.validation_ok
    AND s.quality_status = 'clean'
    AND s.quality_gate_passed
    AND s.operation = 'upsert';
  v_quality_population_hash :=
    public.content_quality_staging_population_manifest_hash(p_import_batch_id);
  IF NOT EXISTS (
    SELECT 1 FROM public.import_batches b
    WHERE b.import_batch_id = p_import_batch_id
      AND b.quality_gate_passed
      AND b.clean_count = v_ok_count
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'batch quality gate evidence is missing or stale', DETAIL = 'QUALITY_GATE_NOT_PASSED';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.content_quality_review_plans plan
    JOIN public.content_quality_review_evidence evidence ON evidence.plan_id = plan.plan_id
    WHERE plan.import_batch_id = p_import_batch_id
      AND evidence.import_batch_id = p_import_batch_id
      AND plan.population_manifest_hash = v_quality_population_hash
      AND evidence.population_manifest_hash = v_quality_population_hash
      AND plan.clean_population_count = (
        SELECT pg_catalog.count(*)::INTEGER
        FROM public.staging_scripts population
        WHERE population.import_batch_id = p_import_batch_id
          AND population.operation = 'upsert'
      )
      AND evidence.publishable_clean_count = v_publishable_upsert_count
      AND evidence.review_quarantined_count = (
        SELECT pg_catalog.count(*)::INTEGER
        FROM public.staging_scripts quarantined
        WHERE quarantined.import_batch_id = p_import_batch_id
          AND quarantined.operation = 'upsert'
          AND quarantined.quality_status = 'quarantined'
      )
      AND evidence.conclusion = 'passed'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'frozen quality review evidence has not passed', DETAIL = 'QUALITY_GATE_NOT_PASSED';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.staging_scripts s
    WHERE s.import_batch_id = p_import_batch_id
      AND s.validation_ok
      AND s.quality_status = 'clean'
      AND s.quality_gate_passed
      AND s.operation = 'withdraw'
      AND NOT EXISTS (
        SELECT 1 FROM public.release_items ri
        WHERE ri.release_id = v_prev AND ri.script_id = s.script_id
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'withdraw target not in current release', DETAIL = 'VALIDATION';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.staging_scripts s
    WHERE s.import_batch_id = p_import_batch_id
      AND s.validation_ok
      AND s.quality_status = 'clean'
      AND s.quality_gate_passed
      AND s.operation = 'upsert'
      AND (
        s.search_document IS NULL
        OR s.search_fallback_text IS NULL
        OR s.content_hash IS DISTINCT FROM
          public.content_governance_hash(
            s.script_id, s.category, s.title, s.answer_text, s.source_ref, s.source_version_id,
            s.owner_role, s.review_due_at, s.platform_scope, s.product_scope_type,
            s.product_scope_refs, s.effective_from, s.effective_to,
            s.intent_taxonomy_version, s.intent_id, s.risk_level, s.risk_categories, s.has_conflict,
            s.review_mode, s.primary_reviewer_id, s.primary_reviewer_role, s.primary_review_evd,
            s.secondary_reviewer_id, s.secondary_reviewer_role, s.secondary_review_evd,
            s.placeholder_keys, s.questions_json
          )
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA001', MESSAGE = 'upsert governance hash/search_document mismatch', DETAIL = 'GOVERNANCE_HASH_MISMATCH';
  END IF;

  -- Register only the non-PII source indirection at the owner-controlled publish boundary. Ordinary
  -- workers cannot write this table or assert promotion/retirement evidence.
  PERFORM pg_catalog.set_config('app.semantic_asset_write', 'publish', true);
  INSERT INTO public.semantic_source_assets(
    source_asset_id, source, origin_fingerprint, origin_fingerprint_key_version,
    source_query_id, promotion_review_ref, promoted_by_role, promoted_at,
    lifecycle, created_at
  )
  SELECT DISTINCT ON (question.value ->> 'source_asset_id')
    question.value ->> 'source_asset_id',
    question.value ->> 'source',
    question.value ->> 'origin_fingerprint',
    question.value ->> 'origin_fingerprint_key_version',
    question.value ->> 'source_query_id',
    question.value ->> 'promotion_review_ref',
    question.value ->> 'promoted_by_role',
    CASE WHEN question.value ->> 'promoted_at' IS NULL THEN NULL
      ELSE (question.value ->> 'promoted_at')::TIMESTAMPTZ END,
    'active',
    pg_catalog.clock_timestamp()
  FROM public.staging_scripts staged
  CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(staged.questions_json) question(value)
  WHERE staged.import_batch_id = p_import_batch_id
    AND staged.validation_ok AND staged.quality_status = 'clean'
    AND staged.quality_gate_passed AND staged.operation = 'upsert'
  ORDER BY question.value ->> 'source_asset_id', staged.script_id,
    question.value ->> 'question_id'
  ON CONFLICT (source_asset_id) DO NOTHING;

  IF EXISTS (
    SELECT 1
    FROM public.staging_scripts staged
    WHERE staged.import_batch_id = p_import_batch_id
      AND staged.validation_ok AND staged.quality_status = 'clean'
      AND staged.quality_gate_passed AND staged.operation = 'upsert'
      AND public.content_questions_source_assets_are_active(staged.questions_json) IS DISTINCT FROM TRUE
  ) OR EXISTS (
    SELECT 1
    FROM public.release_items prior
    WHERE prior.release_id = v_prev
      AND NOT EXISTS (
        SELECT 1 FROM public.import_batch_source_bindings touched
        WHERE touched.import_batch_id = p_import_batch_id AND touched.domain = prior.category
      )
      AND public.content_questions_source_assets_are_active(prior.questions_json) IS DISTINCT FROM TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA004', MESSAGE = 'prospective release uses missing, mismatched or retired semantic source asset', DETAIL = 'SEMANTIC_SOURCE_ASSET_NOT_ACTIVE';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.staging_scripts s
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(s.questions_json) question(value)
    JOIN public.script_questions existing
      ON existing.question_id = question.value ->> 'question_id'
    JOIN public.semantic_source_assets existing_asset
      ON existing_asset.source_asset_id = existing.source_asset_id
    WHERE s.import_batch_id = p_import_batch_id
      AND s.validation_ok AND s.quality_status = 'clean' AND s.quality_gate_passed
      AND s.operation = 'upsert'
      AND (
        existing.script_id IS DISTINCT FROM s.script_id
        OR existing.question_version > (question.value ->> 'question_version')::INTEGER
        OR (
          existing.question_version = (question.value ->> 'question_version')::INTEGER
          AND (
            existing.question_text IS DISTINCT FROM question.value ->> 'question_text'
            OR existing.question_hash IS DISTINCT FROM question.value ->> 'question_hash'
            OR existing.semantic_family_id IS DISTINCT FROM question.value ->> 'semantic_family_id'
            OR existing.origin_fingerprint IS DISTINCT FROM question.value ->> 'origin_fingerprint'
            OR existing.origin_fingerprint_key_version IS DISTINCT FROM question.value ->> 'origin_fingerprint_key_version'
            OR existing.source_asset_id IS DISTINCT FROM question.value ->> 'source_asset_id'
            OR existing.source IS DISTINCT FROM question.value ->> 'source'
            OR existing.intent_taxonomy_version IS DISTINCT FROM question.value ->> 'intent_taxonomy_version'
            OR existing.intent_id IS DISTINCT FROM question.value ->> 'intent_id'
            OR existing.source_query_id IS NOT NULL
            OR existing.promotion_review_ref IS DISTINCT FROM question.value ->> 'promotion_review_ref'
            OR existing.promoted_by_role IS DISTINCT FROM question.value ->> 'promoted_by_role'
            OR existing.promoted_at IS DISTINCT FROM CASE
              WHEN question.value ->> 'promoted_at' IS NULL THEN NULL
              ELSE (question.value ->> 'promoted_at')::TIMESTAMPTZ
            END
            OR existing.status IS DISTINCT FROM 'active'
            OR existing_asset.source_query_id IS DISTINCT FROM question.value ->> 'source_query_id'
            OR existing_asset.lifecycle IS DISTINCT FROM 'active'
          )
        )
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA003', MESSAGE = 'stable question identity conflicts with published lineage', DETAIL = 'QUESTION_IDENTITY_CONFLICT';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.staging_scripts s
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(s.questions_json) question(value)
    LEFT JOIN LATERAL (
      SELECT pg_catalog.max(existing.question_version) AS max_version
      FROM public.script_questions existing
      WHERE existing.question_id = question.value ->> 'question_id'
    ) lineage ON TRUE
    WHERE s.import_batch_id = p_import_batch_id
      AND s.validation_ok AND s.quality_status = 'clean' AND s.quality_gate_passed
      AND s.operation = 'upsert'
      AND (
        (lineage.max_version IS NULL AND (question.value ->> 'question_version')::INTEGER <> 1)
        OR (
          lineage.max_version IS NOT NULL
          AND (question.value ->> 'question_version')::INTEGER > lineage.max_version
          AND (question.value ->> 'question_version')::INTEGER <> lineage.max_version + 1
        )
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZA003', MESSAGE = 'question version must start at one and advance without gaps', DETAIL = 'QUESTION_VERSION_GAP';
  END IF;

  -- A bound domain is a complete snapshot. Archive every prior live row in touched domains first;
  -- staging upserts below republish only rows present in the approved replacement snapshot.
  UPDATE public.scripts sc
  SET status = 'archived', updated_at = now()
  WHERE EXISTS (
    SELECT 1 FROM public.import_batch_source_bindings ib
    WHERE ib.import_batch_id = p_import_batch_id AND ib.domain = sc.category
  );

  -- Upsert live scripts from staging upserts only.
  INSERT INTO public.scripts AS sc (
    script_id, category, title, answer_text, status, version, content_hash,
    source_ref, source_version_id, platform_scope, product_scope_type, product_scope_refs,
    campaign_tag, effective_from, effective_to,
    intent_taxonomy_version, intent_id, risk_level, risk_categories, has_conflict, review_mode,
    primary_reviewer_id, primary_reviewer_role, primary_review_evd,
    secondary_reviewer_id, secondary_reviewer_role, secondary_review_evd,
    placeholder_keys, questions_json,
    priority, owner_role, review_due_at, created_at, updated_at, published_at, tenant_id
  )
  SELECT
    s.script_id, s.category, s.title, s.answer_text, 'published', 1, s.content_hash,
    s.source_ref, s.source_version_id, s.platform_scope, s.product_scope_type, s.product_scope_refs,
    s.campaign_tag, s.effective_from, s.effective_to,
    s.intent_taxonomy_version, s.intent_id, s.risk_level, s.risk_categories, s.has_conflict, s.review_mode,
    s.primary_reviewer_id, s.primary_reviewer_role, s.primary_review_evd,
    s.secondary_reviewer_id, s.secondary_reviewer_role, s.secondary_review_evd,
    s.placeholder_keys, s.questions_json,
    0, s.owner_role, s.review_due_at, now(), now(), now(), 'default'
  FROM public.staging_scripts s
  WHERE s.import_batch_id = p_import_batch_id
    AND s.validation_ok AND s.quality_status = 'clean' AND s.quality_gate_passed
    AND s.operation = 'upsert'
  ON CONFLICT (script_id) DO UPDATE SET
    category = EXCLUDED.category,
    title = EXCLUDED.title,
    answer_text = EXCLUDED.answer_text,
    status = 'published',
    version = sc.version + 1,
    content_hash = EXCLUDED.content_hash,
    source_ref = EXCLUDED.source_ref,
    source_version_id = EXCLUDED.source_version_id,
    platform_scope = EXCLUDED.platform_scope,
    product_scope_type = EXCLUDED.product_scope_type,
    product_scope_refs = EXCLUDED.product_scope_refs,
    campaign_tag = EXCLUDED.campaign_tag,
    effective_from = EXCLUDED.effective_from,
    effective_to = EXCLUDED.effective_to,
    intent_taxonomy_version = EXCLUDED.intent_taxonomy_version,
    intent_id = EXCLUDED.intent_id,
    risk_level = EXCLUDED.risk_level,
    risk_categories = EXCLUDED.risk_categories,
    has_conflict = EXCLUDED.has_conflict,
    review_mode = EXCLUDED.review_mode,
    primary_reviewer_id = EXCLUDED.primary_reviewer_id,
    primary_reviewer_role = EXCLUDED.primary_reviewer_role,
    primary_review_evd = EXCLUDED.primary_review_evd,
    secondary_reviewer_id = EXCLUDED.secondary_reviewer_id,
    secondary_reviewer_role = EXCLUDED.secondary_reviewer_role,
    secondary_review_evd = EXCLUDED.secondary_review_evd,
    placeholder_keys = EXCLUDED.placeholder_keys,
    questions_json = EXCLUDED.questions_json,
    owner_role = EXCLUDED.owner_role,
    review_due_at = EXCLUDED.review_due_at,
    updated_at = now(),
    published_at = now();

  -- Immutable question lineage projection. Existing (question_id,version) rows are never overwritten;
  -- a changed semantic/source/taxonomy mapping must arrive as the next version.
  INSERT INTO public.script_questions AS question (
    question_id, script_id, question_version, question_text, question_hash,
    semantic_family_id, origin_fingerprint, origin_fingerprint_key_version,
    source_asset_id, source, intent_taxonomy_version, intent_id, source_query_id,
    promotion_review_ref, promoted_by_role, promoted_at, status, created_at, updated_at
  )
  SELECT
    payload.question_id, s.script_id, payload.question_version, payload.question_text,
    payload.question_hash, payload.semantic_family_id, payload.origin_fingerprint,
    payload.origin_fingerprint_key_version, payload.source_asset_id, payload.source,
    payload.intent_taxonomy_version, payload.intent_id, NULL,
    payload.promotion_review_ref, payload.promoted_by_role, payload.promoted_at,
    'active', now(), now()
  FROM public.staging_scripts s
  CROSS JOIN LATERAL pg_catalog.jsonb_to_recordset(s.questions_json) AS payload(
    question_id TEXT,
    question_version INTEGER,
    question_text TEXT,
    question_hash TEXT,
    semantic_family_id TEXT,
    origin_fingerprint TEXT,
    origin_fingerprint_key_version TEXT,
    source_asset_id TEXT,
    source TEXT,
    intent_taxonomy_version TEXT,
    intent_id TEXT,
    source_query_id TEXT,
    promotion_review_ref TEXT,
    promoted_by_role TEXT,
    promoted_at TIMESTAMPTZ
  )
  WHERE s.import_batch_id = p_import_batch_id
    AND s.validation_ok AND s.quality_status = 'clean' AND s.quality_gate_passed
    AND s.operation = 'upsert'
  ON CONFLICT (question_id, question_version) DO NOTHING;

  -- Withdraw is an explicit tombstone: archive live material and exclude it from the new snapshot.
  UPDATE public.scripts sc
  SET status = 'archived', updated_at = now()
  FROM public.staging_scripts s
  WHERE s.import_batch_id = p_import_batch_id
    AND s.validation_ok AND s.quality_status = 'clean' AND s.quality_gate_passed
    AND s.operation = 'withdraw'
    AND sc.script_id = s.script_id;

  v_seq := pg_catalog.nextval('public.content_release_seq'::pg_catalog.regclass);
  v_release_id := 'rel_' || v_seq::text;
  v_ann := 'ann_' || v_seq::text;

  UPDATE public.content_releases SET status = 'superseded' WHERE status = 'published';

  INSERT INTO public.content_releases(
    release_id, release_seq, title, summary, import_batch_id, rollback_of_release_id,
    status, source_binding_hash, published_by, published_by_role, published_at, tenant_id
  )
  VALUES (
    v_release_id, v_seq, p_title, p_summary, p_import_batch_id, NULL,
    'published', v_source_hash, p_actor_user_id, p_actor_role, now(), 'default'
  );

  INSERT INTO public.release_source_bindings(release_id, domain, source_version_id, created_at)
  SELECT v_release_id, p.domain, p.source_version_id, now()
  FROM (
    SELECT ib.domain, ib.source_version_id
    FROM public.import_batch_source_bindings ib
    WHERE ib.import_batch_id = p_import_batch_id
    UNION ALL
    SELECT rb.domain, rb.source_version_id
    FROM public.release_source_bindings rb
    WHERE rb.release_id = v_prev
      AND NOT EXISTS (
        SELECT 1 FROM public.import_batch_source_bindings ib
        WHERE ib.import_batch_id = p_import_batch_id AND ib.domain = rb.domain
      )
  ) p;

  -- MERGE by authoritative domain: prior rows from every touched domain are removed as one unit.
  INSERT INTO public.release_items(
    release_id, script_id, script_version, content_hash, answer_text, title, category,
    source_ref, source_version_id, owner_role, review_due_at,
    effective_from, effective_to, platform_scope, product_scope_type, product_scope_refs,
    intent_taxonomy_version, intent_id, risk_level, risk_categories, has_conflict, review_mode,
    primary_reviewer_id, primary_reviewer_role, primary_review_evd,
    secondary_reviewer_id, secondary_reviewer_role, secondary_review_evd,
    placeholder_keys, questions_json,
    search_document, search_fallback_text
  )
  SELECT
    v_release_id, x.script_id, x.script_version, x.content_hash, x.answer_text, x.title, x.category,
    x.source_ref, x.source_version_id, x.owner_role, x.review_due_at,
    x.effective_from, x.effective_to, x.platform_scope, x.product_scope_type, x.product_scope_refs,
    x.intent_taxonomy_version, x.intent_id, x.risk_level, x.risk_categories, x.has_conflict, x.review_mode,
    x.primary_reviewer_id, x.primary_reviewer_role, x.primary_review_evd,
    x.secondary_reviewer_id, x.secondary_reviewer_role, x.secondary_review_evd,
    x.placeholder_keys, x.questions_json,
    x.search_document, x.search_fallback_text
  FROM (
    -- upsert wins
    SELECT
      s.script_id, sc.version AS script_version, s.content_hash, s.answer_text, s.title, s.category,
      s.source_ref, s.source_version_id, s.owner_role, s.review_due_at,
      s.effective_from, s.effective_to, s.platform_scope, s.product_scope_type, s.product_scope_refs,
      s.intent_taxonomy_version, s.intent_id, s.risk_level, s.risk_categories, s.has_conflict, s.review_mode,
      s.primary_reviewer_id, s.primary_reviewer_role, s.primary_review_evd,
      s.secondary_reviewer_id, s.secondary_reviewer_role, s.secondary_review_evd,
      s.placeholder_keys, s.questions_json,
      s.search_document, s.search_fallback_text
    FROM public.staging_scripts s
    JOIN public.scripts sc ON sc.script_id = s.script_id
    WHERE s.import_batch_id = p_import_batch_id
      AND s.validation_ok AND s.quality_status = 'clean' AND s.quality_gate_passed
      AND s.operation = 'upsert'
    UNION ALL
    -- previous rows not mentioned by either upsert or withdraw remain
    SELECT
      ri.script_id, ri.script_version, ri.content_hash, ri.answer_text, ri.title, ri.category,
      ri.source_ref, ri.source_version_id, ri.owner_role, ri.review_due_at,
      ri.effective_from, ri.effective_to, ri.platform_scope, ri.product_scope_type, ri.product_scope_refs,
      ri.intent_taxonomy_version, ri.intent_id, ri.risk_level, ri.risk_categories, ri.has_conflict, ri.review_mode,
      ri.primary_reviewer_id, ri.primary_reviewer_role, ri.primary_review_evd,
      ri.secondary_reviewer_id, ri.secondary_reviewer_role, ri.secondary_review_evd,
      ri.placeholder_keys, ri.questions_json,
      ri.search_document, ri.search_fallback_text
    FROM public.release_items ri
    WHERE v_prev IS NOT NULL
      AND ri.release_id = v_prev
      AND NOT EXISTS (
        SELECT 1 FROM public.import_batch_source_bindings ib
        WHERE ib.import_batch_id = p_import_batch_id AND ib.domain = ri.category
      )
  ) x;

  INSERT INTO public.content_current(id, current_release_id, updated_at)
  VALUES (1, v_release_id, now())
  ON CONFLICT (id) DO UPDATE SET current_release_id = EXCLUDED.current_release_id, updated_at = now();

  INSERT INTO public.announcements(announcement_id, release_id, title, summary, created_at)
  VALUES (v_ann, v_release_id, COALESCE(p_title, '话术库更新'), p_summary, now());

  UPDATE public.import_batches SET status = 'published', finished_at = now()
  WHERE import_batch_id = p_import_batch_id;

  INSERT INTO public.change_audits(
    change_id, action, actor_role, actor_user_id, source, metadata, created_at
  ) VALUES (
    'chg_' || pg_catalog.gen_random_uuid()::text,
    'content_publish', p_actor_role, p_actor_user_id, 'publish_content_release',
    pg_catalog.jsonb_build_object(
      'release_id', v_release_id,
      'previous_release_id', v_prev,
      'import_batch_id', p_import_batch_id,
      'source_binding_hash', v_source_hash
    ),
    now()
  );

  release_id := v_release_id;
  release_seq := v_seq;
  announcement_id := v_ann;
  source_binding_hash := v_source_hash;
  RETURN NEXT;
END;
$$;
REVOKE ALL ON FUNCTION publish_content_release(TEXT,TEXT,TEXT,TEXT,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION publish_content_release(TEXT,TEXT,TEXT,TEXT,TEXT) TO app_content_admin;
-- END COACH PUBLISH

-- BEGIN CONTENT INTAKE 4d0565bd4b8db0da2aa80523b0ea64ad9f9bd48604c534549d04fe07533ec840
-- schema.v1.20 CANDIDATE: additive storage contract, NOT a runtime implementation.
-- Applications receive NO new grants. After freeze/intake, product migrations must
-- implement the transaction obligations in 13-P2资料接入合同候选.md before activation.
-- Existing content_current remains the only publication pointer.
BEGIN;
CREATE SCHEMA content_intake;
REVOKE ALL ON SCHEMA content_intake FROM PUBLIC;
CREATE DOMAIN content_intake.identifier AS TEXT
  CHECK (VALUE ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$');
CREATE DOMAIN content_intake.sha256 AS TEXT CHECK (VALUE ~ '^[0-9a-f]{64}$');
CREATE DOMAIN content_intake.version AS BIGINT CHECK (VALUE BETWEEN 1 AND 9007199254740991);
CREATE DOMAIN content_intake.generation AS BIGINT CHECK (VALUE BETWEEN 0 AND 9007199254740991);

-- Identity facts are immutable history; current_facts_version is a fact pointer,
-- never a second content pointer. person_key is confirmed only within identity_scope.
CREATE TABLE content_intake.principals (
  principal_id content_intake.identifier PRIMARY KEY,
  user_id TEXT NOT NULL UNIQUE REFERENCES backend_identity.subject_bindings(user_id),
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  identity_scope content_intake.identifier NOT NULL,
  person_key content_intake.identifier NOT NULL,
  current_facts_version content_intake.version NOT NULL,
  revocation_generation content_intake.generation NOT NULL DEFAULT 0,
  UNIQUE (principal_id,tenant_id,app_id),
  UNIQUE (principal_id,user_id),
  UNIQUE (tenant_id,app_id,identity_scope,person_key)
);
CREATE TABLE content_intake.principal_facts (
  principal_id content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  facts_version content_intake.version NOT NULL,
  department_ids TEXT[] NOT NULL CHECK (cardinality(department_ids) BETWEEN 1 AND 100 AND array_position(department_ids,NULL) IS NULL),
  job_id content_intake.identifier NOT NULL,
  enabled BOOLEAN NOT NULL,
  checked_at TIMESTAMPTZ NOT NULL CHECK (isfinite(checked_at)),
  valid_until TIMESTAMPTZ NOT NULL,
  facts_digest content_intake.sha256 NOT NULL,
  PRIMARY KEY (principal_id,facts_version),
  CHECK (valid_until > checked_at AND valid_until <= checked_at + INTERVAL '5 minutes')
);
ALTER TABLE content_intake.principals ADD CONSTRAINT principal_current_facts_fk
  FOREIGN KEY (principal_id,current_facts_version) REFERENCES content_intake.principal_facts
  DEFERRABLE INITIALLY DEFERRED;
-- Tenant/app policy CAS is independent of per-rule historical versions.
CREATE TABLE content_intake.policy_versions (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  version content_intake.version NOT NULL,
  PRIMARY KEY (tenant_id,app_id)
);
CREATE TABLE content_intake.role_rules (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  department_id content_intake.identifier NOT NULL,
  job_id content_intake.identifier NOT NULL,
  policy_version content_intake.version NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('agent','enabler','lead','supervisor','manager','director')),
  PRIMARY KEY (tenant_id,app_id,department_id,job_id)
);
CREATE TABLE content_intake.scopes (
  scope_id content_intake.identifier PRIMARY KEY,
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  brand_id content_intake.identifier NOT NULL,
  shop_id content_intake.identifier,
  domain TEXT NOT NULL CHECK (domain IN ('presale','campaign','aftersale','product')),
  UNIQUE NULLS NOT DISTINCT (tenant_id,app_id,brand_id,shop_id,domain),
  UNIQUE (scope_id,tenant_id,app_id)
);
CREATE TABLE content_intake.sources (
  source_id content_intake.identifier PRIMARY KEY,
  scope_id content_intake.identifier NOT NULL REFERENCES content_intake.scopes,
  current_mapping_version content_intake.version NOT NULL,
  mode TEXT NOT NULL DEFAULT 'legacy' CHECK (mode IN ('legacy','v2-preview','v2-active')),
  mode_version content_intake.version NOT NULL DEFAULT 1,
  revocation_generation content_intake.generation NOT NULL DEFAULT 0,
  UNIQUE (source_id,scope_id)
);
CREATE TABLE content_intake.source_mappings (
  source_id content_intake.identifier NOT NULL REFERENCES content_intake.sources,
  version content_intake.version NOT NULL,
  template_version TEXT NOT NULL CHECK (length(template_version) BETWEEN 1 AND 64),
  rule_version TEXT NOT NULL CHECK (length(rule_version) BETWEEN 1 AND 64),
  mapping_version TEXT NOT NULL CHECK (length(mapping_version) BETWEEN 1 AND 64),
  structure_digest content_intake.sha256 NOT NULL,
  PRIMARY KEY (source_id,version)
);
ALTER TABLE content_intake.sources ADD CONSTRAINT source_current_mapping_fk
  FOREIGN KEY (source_id,current_mapping_version) REFERENCES content_intake.source_mappings
  DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE content_intake.grants (
  grant_id content_intake.identifier PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('business','allocation','delegation')),
  issuer_id content_intake.identifier NOT NULL,
  recipient_id content_intake.identifier NOT NULL,
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  scope_id content_intake.identifier NOT NULL,
  source_id content_intake.identifier,
  action TEXT NOT NULL CHECK (action IN ('query','content-manage','import','source-confirm','review','publish','candidate-cancel','rollback')),
  starts_at TIMESTAMPTZ NOT NULL CHECK (isfinite(starts_at)),
  expires_at TIMESTAMPTZ NOT NULL CHECK (isfinite(expires_at) AND expires_at > starts_at),
  revoked_at TIMESTAMPTZ,
  steward_id content_intake.identifier,
  version content_intake.version NOT NULL DEFAULT 1,
  reason TEXT NOT NULL CHECK (length(btrim(reason)) BETWEEN 1 AND 512),
  -- Creation reason is immutable; each later version adds its own request reason.
  last_change_reason TEXT CHECK (last_change_reason IS NULL OR length(btrim(last_change_reason)) BETWEEN 1 AND 512),
  CHECK ((version = 1 AND last_change_reason IS NULL) OR (version > 1 AND last_change_reason IS NOT NULL)),
  parent_grant_id content_intake.identifier REFERENCES content_intake.grants,
  may_redelegate BOOLEAN NOT NULL DEFAULT FALSE CHECK (may_redelegate = FALSE),
  FOREIGN KEY (issuer_id,tenant_id,app_id) REFERENCES content_intake.principals(principal_id,tenant_id,app_id),
  FOREIGN KEY (steward_id,tenant_id,app_id) REFERENCES content_intake.principals(principal_id,tenant_id,app_id),
  FOREIGN KEY (recipient_id,tenant_id,app_id) REFERENCES content_intake.principals(principal_id,tenant_id,app_id),
  FOREIGN KEY (scope_id,tenant_id,app_id) REFERENCES content_intake.scopes(scope_id,tenant_id,app_id),
  FOREIGN KEY (source_id,scope_id) REFERENCES content_intake.sources(source_id,scope_id),
  CHECK (kind = 'allocation' OR issuer_id <> recipient_id),
  CHECK (kind = 'allocation' OR parent_grant_id IS NOT NULL)
);
CREATE INDEX grants_recipient_scope ON content_intake.grants(recipient_id,scope_id,action,expires_at) WHERE revoked_at IS NULL;
CREATE INDEX grants_parent ON content_intake.grants(parent_grant_id);
CREATE FUNCTION content_intake.grant_version_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='GRANT_HISTORY_REQUIRED'; END IF;
  IF NEW.version<>OLD.version+1 OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
    OR (to_jsonb(NEW)-ARRAY['version','revoked_at','steward_id','last_change_reason']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['version','revoked_at','steward_id','last_change_reason']) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='GRANT_VERSION_OR_IDENTITY_CHANGED';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER grant_version BEFORE UPDATE OR DELETE ON content_intake.grants FOR EACH ROW EXECUTE FUNCTION content_intake.grant_version_guard();
CREATE TABLE content_intake.grant_history (
  grant_id content_intake.identifier NOT NULL REFERENCES content_intake.grants,
  version content_intake.version NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL,
  record JSONB NOT NULL CHECK (jsonb_typeof(record)='object'),
  PRIMARY KEY (grant_id,version)
);
CREATE TABLE content_intake.role_rule_history (
  event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recorded_at TIMESTAMPTZ NOT NULL,
  before_record JSONB,
  after_record JSONB,
  CHECK (before_record IS NOT NULL OR after_record IS NOT NULL)
);
CREATE FUNCTION content_intake.record_policy_history() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_TABLE_NAME='grants' THEN
    INSERT INTO content_intake.grant_history VALUES (NEW.grant_id,NEW.version,clock_timestamp(),to_jsonb(NEW));
  ELSE
    INSERT INTO content_intake.policy_versions VALUES (coalesce(NEW.tenant_id,OLD.tenant_id),coalesce(NEW.app_id,OLD.app_id),1)
      ON CONFLICT (tenant_id,app_id) DO UPDATE SET version=content_intake.policy_versions.version+1;
    INSERT INTO content_intake.role_rule_history(recorded_at,before_record,after_record)
      VALUES (clock_timestamp(),CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END);
  END IF;
  RETURN NULL;
END;
$$;
CREATE TRIGGER grant_history AFTER INSERT OR UPDATE ON content_intake.grants FOR EACH ROW EXECUTE FUNCTION content_intake.record_policy_history();
CREATE TRIGGER role_history AFTER INSERT OR UPDATE OR DELETE ON content_intake.role_rules FOR EACH ROW EXECUTE FUNCTION content_intake.record_policy_history();

-- Concrete-source current business authorization only. Grant creation and historical
-- review eligibility are separate transaction obligations, never inferred from this helper.
CREATE FUNCTION content_intake.authorization_deadline(
  p_principal TEXT, p_action TEXT, p_scope TEXT, p_source TEXT, p_at TIMESTAMPTZ
) RETURNS TIMESTAMPTZ LANGUAGE SQL STABLE SET search_path = pg_catalog AS $$
  SELECT least(f.valid_until,max(g.expires_at))
  FROM content_intake.principals p
  JOIN content_intake.principal_facts f ON f.principal_id=p.principal_id AND f.facts_version=p.current_facts_version
  JOIN content_intake.scopes s ON s.scope_id=p_scope AND s.tenant_id=p.tenant_id AND s.app_id=p.app_id
  JOIN content_intake.grants g ON g.recipient_id=p.principal_id AND g.scope_id=s.scope_id
    AND g.action=p_action AND g.kind='business' AND g.revoked_at IS NULL
    AND (g.source_id IS NULL OR g.source_id=p_source) AND g.starts_at<=p_at AND p_at<g.expires_at
  JOIN content_intake.role_rules r ON r.tenant_id=p.tenant_id AND r.app_id=p.app_id
    AND r.department_id=ANY(f.department_ids) AND r.job_id=f.job_id
  WHERE p.principal_id=p_principal AND f.enabled AND f.checked_at<=p_at AND p_at<f.valid_until
    AND EXISTS (SELECT 1 FROM content_intake.sources src WHERE src.source_id=p_source AND src.scope_id=s.scope_id)
  GROUP BY f.valid_until
  HAVING count(DISTINCT r.role)=1 AND (min(r.role)<>'agent' OR p_action='query')
$$;

CREATE TABLE content_intake.vocabulary (
  vocabulary_id content_intake.identifier PRIMARY KEY,
  scope_id content_intake.identifier NOT NULL REFERENCES content_intake.scopes,
  kind TEXT NOT NULL CHECK (kind IN ('product','scenario')),
  meaning_digest content_intake.sha256 NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (vocabulary_id,scope_id)
);
CREATE TABLE content_intake.vocabulary_displays (
  vocabulary_id content_intake.identifier NOT NULL REFERENCES content_intake.vocabulary,
  display_version content_intake.version NOT NULL,
  display_name TEXT NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 256),
  PRIMARY KEY (vocabulary_id,display_version)
);
CREATE TABLE content_intake.objects (
  object_id content_intake.identifier PRIMARY KEY,
  source_id content_intake.identifier REFERENCES content_intake.sources,
  actor_id content_intake.identifier NOT NULL,
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  object_key TEXT NOT NULL UNIQUE CHECK (object_key ~ '^intake/[A-Za-z0-9._/-]{1,200}$' AND object_key NOT LIKE '%..%'),
  sha256 content_intake.sha256 NOT NULL,
  bytes BIGINT NOT NULL CHECK (bytes BETWEEN 1 AND 52428800),
  mime TEXT NOT NULL CHECK (mime IN ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/pdf','application/json')),
  purpose TEXT NOT NULL CHECK (purpose IN ('input','report','review-package')),
  received_at TIMESTAMPTZ NOT NULL,
  UNIQUE (object_id,source_id,sha256),
  UNIQUE (object_id,source_id),
  UNIQUE (object_id,sha256),
  FOREIGN KEY (actor_id,tenant_id,app_id) REFERENCES content_intake.principals(principal_id,tenant_id,app_id),
  CHECK (source_id IS NOT NULL OR purpose='review-package'),
  CHECK (purpose<>'input' OR (bytes<=10485760 AND mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'))
);
CREATE TABLE content_intake.parse_jobs (
  job_id content_intake.identifier PRIMARY KEY,
  source_version content_intake.version NOT NULL,
  contributor_ids content_intake.identifier[] NOT NULL CHECK (cardinality(contributor_ids) BETWEEN 1 AND 100 AND array_position(contributor_ids,NULL) IS NULL),
  generation content_intake.version NOT NULL,
  source_id content_intake.identifier NOT NULL REFERENCES content_intake.sources,
  object_id content_intake.identifier NOT NULL REFERENCES content_intake.objects,
  actor_id content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  state TEXT NOT NULL CHECK (state IN ('reading','parsing','validated','failed','cancelled')),
  base_release_id TEXT REFERENCES public.content_releases,
  report_object_id content_intake.identifier REFERENCES content_intake.objects,
  started_at TIMESTAMPTZ NOT NULL,
  finished_at TIMESTAMPTZ,
  expected_prior_id content_intake.identifier,
  expected_prior_version content_intake.version,
  expected_prior_digest content_intake.sha256,
  result_candidate_id content_intake.identifier,
  result_candidate_version content_intake.version,
  CHECK ((expected_prior_id IS NULL AND expected_prior_version IS NULL AND expected_prior_digest IS NULL)
    OR (expected_prior_id IS NOT NULL AND expected_prior_version IS NOT NULL AND expected_prior_digest IS NOT NULL)),
  CHECK ((result_candidate_id IS NULL)=(result_candidate_version IS NULL)),
  CHECK ((state='validated')=(result_candidate_id IS NOT NULL)),
  FOREIGN KEY (source_id,source_version) REFERENCES content_intake.source_mappings,
  FOREIGN KEY (object_id,source_id) REFERENCES content_intake.objects(object_id,source_id),
  FOREIGN KEY (report_object_id,source_id) REFERENCES content_intake.objects(object_id,source_id),
  CHECK ((state IN ('validated','failed','cancelled')) = (finished_at IS NOT NULL))
);
CREATE TABLE content_intake.candidate_versions (
  candidate_id content_intake.identifier NOT NULL,
  version content_intake.version NOT NULL,
  source_id content_intake.identifier NOT NULL,
  scope_id content_intake.identifier NOT NULL,
  source_version content_intake.version NOT NULL,
  object_id content_intake.identifier NOT NULL,
  file_sha256 content_intake.sha256 NOT NULL,
  actor_id content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  base_release_id TEXT REFERENCES public.content_releases,
  canonical_encoding TEXT NOT NULL CHECK (canonical_encoding='candidate-p1.1'),
  canonical_material TEXT NOT NULL CHECK (octet_length(canonical_material) BETWEEN 2 AND 52428800),
  material JSONB NOT NULL CHECK (jsonb_typeof(material)='object'),
  digest TEXT GENERATED ALWAYS AS (encode(public.digest(canonical_material,'sha256'),'hex')) STORED,
  risk TEXT NOT NULL CHECK (risk IN ('routine','critical')),
  explicit_disable_count INTEGER NOT NULL CHECK (explicit_disable_count BETWEEN 0 AND 5000),
  state TEXT NOT NULL DEFAULT 'awaiting-evidence' CHECK (state IN ('awaiting-evidence','ready','publishing','published','cancelled','invalidated')),
  source_evidence_version content_intake.generation NOT NULL DEFAULT 0,
  approval_evidence_version content_intake.generation NOT NULL DEFAULT 0,
  revocation_generation content_intake.generation NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (candidate_id,version),
  UNIQUE (candidate_id,version,digest),
  UNIQUE (candidate_id,version,source_id),
  UNIQUE (candidate_id,version,file_sha256),
  UNIQUE (candidate_id,version,object_id),
  FOREIGN KEY (source_id,scope_id) REFERENCES content_intake.sources(source_id,scope_id),
  FOREIGN KEY (source_id,source_version) REFERENCES content_intake.source_mappings,
  FOREIGN KEY (object_id,source_id,file_sha256) REFERENCES content_intake.objects(object_id,source_id,sha256),
  CHECK (canonical_material::jsonb=material),
  CHECK (material->>'canonicalEncodingVersion' IS NOT DISTINCT FROM canonical_encoding),
  CHECK (material#>>'{scope,sourceId}' IS NOT DISTINCT FROM source_id::text),
  CHECK (material#>>'{object,objectId}' IS NOT DISTINCT FROM object_id::text),
  CHECK (material#>>'{object,sha256}' IS NOT DISTINCT FROM file_sha256::text),
  CHECK (material#>>'{sourceClaim,fileSha256}' IS NOT DISTINCT FROM file_sha256::text),
  CHECK (jsonb_typeof(material->'contributors') IS NOT DISTINCT FROM 'array'),
  CHECK (jsonb_array_length(material->'contributors') BETWEEN 1 AND 100),
  CHECK (material->>'baseReleaseId' IS NOT DISTINCT FROM base_release_id),
  CHECK (material#>>'{risk,level}' IS NOT DISTINCT FROM risk),
  CHECK (material#>>'{risk,explicitDisableCount}' IS NOT DISTINCT FROM explicit_disable_count::text),
  CHECK (explicit_disable_count<2 OR risk='critical'),
  CHECK (state NOT IN ('ready','publishing','published') OR (source_evidence_version>0 AND approval_evidence_version>0)),
  CHECK (updated_at>=created_at)
);
CREATE UNIQUE INDEX candidate_one_open_version ON content_intake.candidate_versions(candidate_id)
  WHERE state IN ('awaiting-evidence','ready','publishing');
CREATE INDEX candidate_scope_state_updated ON content_intake.candidate_versions(scope_id,state,updated_at DESC,candidate_id,version);
CREATE INDEX candidate_source_state_updated ON content_intake.candidate_versions(source_id,state,updated_at DESC,candidate_id,version);
CREATE INDEX candidate_actor_open ON content_intake.candidate_versions(actor_id) WHERE state IN ('awaiting-evidence','ready','publishing');
ALTER TABLE content_intake.parse_jobs
  ADD FOREIGN KEY (expected_prior_id,expected_prior_version,expected_prior_digest) REFERENCES content_intake.candidate_versions(candidate_id,version,digest),
  ADD FOREIGN KEY (expected_prior_id,expected_prior_version,source_id) REFERENCES content_intake.candidate_versions(candidate_id,version,source_id),
  ADD FOREIGN KEY (result_candidate_id,result_candidate_version,source_id) REFERENCES content_intake.candidate_versions(candidate_id,version,source_id),
  ADD FOREIGN KEY (result_candidate_id,result_candidate_version,object_id) REFERENCES content_intake.candidate_versions(candidate_id,version,object_id);
-- The frozen material owns contributors. A derived view cannot diverge from its digest.
CREATE VIEW content_intake.contributors AS
  SELECT candidate_id,version AS candidate_version,
    jsonb_array_elements_text(material->'contributors')::content_intake.identifier AS principal_id
  FROM content_intake.candidate_versions;
CREATE TABLE content_intake.candidate_vocabulary (
  candidate_id content_intake.identifier NOT NULL,
  candidate_version content_intake.version NOT NULL,
  vocabulary_id content_intake.identifier NOT NULL,
  display_version content_intake.version NOT NULL,
  PRIMARY KEY (candidate_id,candidate_version,vocabulary_id),
  FOREIGN KEY (candidate_id,candidate_version) REFERENCES content_intake.candidate_versions,
  FOREIGN KEY (vocabulary_id,display_version) REFERENCES content_intake.vocabulary_displays
);
CREATE TABLE content_intake.source_confirmations (
  candidate_id content_intake.identifier NOT NULL,
  candidate_version content_intake.version NOT NULL,
  candidate_digest content_intake.sha256 NOT NULL,
  source_id content_intake.identifier NOT NULL,
  evidence_version content_intake.version NOT NULL,
  revocation_generation content_intake.generation NOT NULL DEFAULT 0,
  version_kind TEXT NOT NULL CHECK (version_kind IN ('integer','opaque')),
  version_value TEXT NOT NULL CHECK (length(version_value) BETWEEN 1 AND 128),
  acquisition TEXT NOT NULL CHECK (acquisition IN ('feishu-export','controlled-synthetic-export')),
  confirmed_by content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  confirmed_at TIMESTAMPTZ NOT NULL,
  object_sha256 content_intake.sha256 NOT NULL,
  PRIMARY KEY (candidate_id,candidate_version,evidence_version),
  FOREIGN KEY (candidate_id,candidate_version,candidate_digest) REFERENCES content_intake.candidate_versions(candidate_id,version,digest),
  FOREIGN KEY (candidate_id,candidate_version,source_id) REFERENCES content_intake.candidate_versions(candidate_id,version,source_id),
  FOREIGN KEY (candidate_id,candidate_version,object_sha256) REFERENCES content_intake.candidate_versions(candidate_id,version,file_sha256),
  CHECK (version_kind<>'integer' OR version_value ~ '^(0|[1-9][0-9]{0,18})$')
);
CREATE TABLE content_intake.rollback_plans (
  rollback_plan_id content_intake.identifier PRIMARY KEY,
  base_release_id TEXT NOT NULL REFERENCES public.content_releases,
  target_release_id TEXT NOT NULL REFERENCES public.content_releases,
  impact_digest content_intake.sha256 NOT NULL,
  actor_id content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE (rollback_plan_id,impact_digest),
  CHECK (base_release_id<>target_release_id)
);
CREATE TABLE content_intake.rollback_scopes (
  rollback_plan_id content_intake.identifier NOT NULL REFERENCES content_intake.rollback_plans,
  source_id content_intake.identifier NOT NULL REFERENCES content_intake.sources,
  PRIMARY KEY (rollback_plan_id,source_id)
);
CREATE TABLE content_intake.review_bindings (
  review_request_id content_intake.identifier PRIMARY KEY,
  candidate_id content_intake.identifier,
  candidate_version content_intake.version,
  candidate_digest content_intake.sha256,
  rollback_plan_id content_intake.identifier,
  impact_digest content_intake.sha256,
  evidence_version content_intake.version NOT NULL,
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  definition_id content_intake.identifier NOT NULL,
  node_id content_intake.identifier NOT NULL,
  create_uuid UUID NOT NULL UNIQUE,
  instance_code content_intake.identifier,
  package_object_id content_intake.identifier NOT NULL REFERENCES content_intake.objects,
  package_sha256 content_intake.sha256 NOT NULL,
  attachment_file_code TEXT CHECK (length(attachment_file_code) BETWEEN 1 AND 512),
  UNIQUE (candidate_id,candidate_version,evidence_version),
  UNIQUE (review_request_id,candidate_id,candidate_version),
  UNIQUE (rollback_plan_id,evidence_version),
  UNIQUE (tenant_id,app_id,instance_code),
  FOREIGN KEY (package_object_id,package_sha256) REFERENCES content_intake.objects(object_id,sha256),
  FOREIGN KEY (candidate_id,candidate_version,candidate_digest) REFERENCES content_intake.candidate_versions(candidate_id,version,digest),
  FOREIGN KEY (rollback_plan_id,impact_digest) REFERENCES content_intake.rollback_plans(rollback_plan_id,impact_digest),
  CHECK ((candidate_id IS NOT NULL AND candidate_version IS NOT NULL AND candidate_digest IS NOT NULL AND rollback_plan_id IS NULL AND impact_digest IS NULL)
    OR (candidate_id IS NULL AND candidate_version IS NULL AND candidate_digest IS NULL AND rollback_plan_id IS NOT NULL AND impact_digest IS NOT NULL))
);
CREATE TABLE content_intake.approval_facts (
  review_request_id content_intake.identifier NOT NULL REFERENCES content_intake.review_bindings,
  facts_version content_intake.version NOT NULL,
  revocation_generation content_intake.generation NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('pending','approved','rejected','revoked')),
  checked_at TIMESTAMPTZ NOT NULL CHECK (isfinite(checked_at)),
  valid_until TIMESTAMPTZ NOT NULL,
  raw_facts_digest content_intake.sha256 NOT NULL,
  package_verified_sha256 content_intake.sha256,
  human_task_id content_intake.identifier,
  reviewer_id content_intake.identifier,
  reviewer_facts_version content_intake.version,
  decided_at TIMESTAMPTZ,
  PRIMARY KEY (review_request_id,facts_version),
  FOREIGN KEY (reviewer_id,reviewer_facts_version) REFERENCES content_intake.principal_facts,
  CHECK (valid_until>checked_at AND valid_until<=checked_at+INTERVAL '5 minutes'),
  CHECK (state<>'approved' OR (human_task_id IS NOT NULL AND reviewer_id IS NOT NULL AND reviewer_facts_version IS NOT NULL AND decided_at IS NOT NULL AND decided_at<=checked_at AND package_verified_sha256 IS NOT NULL))
);
CREATE TABLE content_intake.approval_current (
  review_request_id content_intake.identifier PRIMARY KEY,
  facts_version content_intake.version NOT NULL,
  FOREIGN KEY (review_request_id,facts_version) REFERENCES content_intake.approval_facts
);
-- One durable operation namespace for publish/cancel/rollback, with a typed target.
-- Recovery never depends only on the 24-hour response cache.
CREATE TABLE content_intake.write_attempts (
  actor_id content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  operation_id content_intake.identifier NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('publish','cancel','rollback')),
  candidate_id content_intake.identifier,
  candidate_version content_intake.version,
  candidate_digest content_intake.sha256,
  rollback_plan_id content_intake.identifier,
  impact_digest content_intake.sha256,
  payload_digest content_intake.sha256 NOT NULL,
  base_release_id TEXT REFERENCES public.content_releases,
  source_evidence_version content_intake.version,
  approval_evidence_version content_intake.version,
  import_batch_id TEXT UNIQUE REFERENCES public.import_batches,
  state TEXT NOT NULL CHECK (state IN ('pending','unknown','published','cancelled','failed')),
  created_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (actor_id,action,operation_id),
  UNIQUE (actor_id,action,operation_id,candidate_id,candidate_version),
  UNIQUE (actor_id,action,operation_id,rollback_plan_id),
  FOREIGN KEY (candidate_id,candidate_version,candidate_digest) REFERENCES content_intake.candidate_versions(candidate_id,version,digest),
  FOREIGN KEY (candidate_id,candidate_version,source_evidence_version) REFERENCES content_intake.source_confirmations,
  FOREIGN KEY (candidate_id,candidate_version,approval_evidence_version) REFERENCES content_intake.review_bindings(candidate_id,candidate_version,evidence_version),
  FOREIGN KEY (rollback_plan_id,impact_digest) REFERENCES content_intake.rollback_plans(rollback_plan_id,impact_digest),
  FOREIGN KEY (rollback_plan_id,approval_evidence_version) REFERENCES content_intake.review_bindings(rollback_plan_id,evidence_version),
  CHECK ((action IN ('publish','cancel') AND candidate_id IS NOT NULL AND candidate_version IS NOT NULL AND candidate_digest IS NOT NULL AND rollback_plan_id IS NULL AND impact_digest IS NULL)
    OR (action='rollback' AND candidate_id IS NULL AND candidate_version IS NULL AND candidate_digest IS NULL AND rollback_plan_id IS NOT NULL AND impact_digest IS NOT NULL)),
  CHECK ((action='publish' AND source_evidence_version IS NOT NULL AND approval_evidence_version IS NOT NULL)
    OR (action='cancel' AND source_evidence_version IS NULL AND approval_evidence_version IS NULL AND import_batch_id IS NULL)
    OR (action='rollback' AND source_evidence_version IS NULL AND approval_evidence_version IS NOT NULL AND import_batch_id IS NULL))
);
CREATE UNIQUE INDEX candidate_one_uncertain_attempt ON content_intake.write_attempts(candidate_id,candidate_version)
  WHERE action='publish' AND state IN ('pending','unknown');
CREATE UNIQUE INDEX rollback_one_uncertain_attempt ON content_intake.write_attempts(rollback_plan_id)
  WHERE action='rollback' AND state IN ('pending','unknown');
ALTER TABLE public.announcements ADD CONSTRAINT announcement_release_identity UNIQUE (announcement_id,release_id);
-- One permanent publication identity across normal publication and full rollback.
-- Lifetime does not follow idempotency_keys' 24h cache; rows cannot be deleted.
CREATE TABLE content_intake.publications (
  candidate_id content_intake.identifier,
  candidate_version content_intake.version,
  rollback_plan_id content_intake.identifier,
  actor_id content_intake.identifier NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('publish','rollback')),
  operation_id content_intake.identifier NOT NULL,
  release_id TEXT PRIMARY KEY REFERENCES public.content_releases,
  announcement_id TEXT NOT NULL UNIQUE REFERENCES public.announcements,
  UNIQUE (candidate_id,candidate_version),
  UNIQUE (rollback_plan_id),
  UNIQUE (actor_id,action,operation_id),
  FOREIGN KEY (candidate_id,candidate_version) REFERENCES content_intake.candidate_versions,
  FOREIGN KEY (actor_id,action,operation_id,candidate_id,candidate_version) REFERENCES content_intake.write_attempts(actor_id,action,operation_id,candidate_id,candidate_version),
  FOREIGN KEY (actor_id,action,operation_id,rollback_plan_id) REFERENCES content_intake.write_attempts(actor_id,action,operation_id,rollback_plan_id),
  FOREIGN KEY (announcement_id,release_id) REFERENCES public.announcements(announcement_id,release_id),
  CHECK ((action='publish' AND candidate_id IS NOT NULL AND candidate_version IS NOT NULL AND rollback_plan_id IS NULL)
    OR (action='rollback' AND candidate_id IS NULL AND candidate_version IS NULL AND rollback_plan_id IS NOT NULL))
);
CREATE TABLE content_intake.commit_tickets (
  ticket_hash content_intake.sha256 PRIMARY KEY,
  actor_id content_intake.identifier NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('publish','rollback')),
  operation_id content_intake.identifier NOT NULL,
  candidate_generation content_intake.generation,
  actor_facts_version content_intake.version NOT NULL,
  actor_generation content_intake.generation NOT NULL,
  reviewer_facts_version content_intake.version NOT NULL,
  reviewer_generation content_intake.generation NOT NULL,
  approval_facts_version content_intake.version NOT NULL,
  approval_generation content_intake.generation NOT NULL,
  issued_at TIMESTAMPTZ NOT NULL CHECK (isfinite(issued_at)),
  expires_at TIMESTAMPTZ NOT NULL,
  consumed_at TIMESTAMPTZ,
  FOREIGN KEY (actor_id,action,operation_id) REFERENCES content_intake.write_attempts,
  CHECK ((action='publish')=(candidate_generation IS NOT NULL)),
  CHECK (expires_at>issued_at AND expires_at<=issued_at+INTERVAL '60 seconds'),
  CHECK (consumed_at IS NULL OR (consumed_at>=issued_at AND consumed_at<expires_at))
);
-- Exact affected source set (including rollback) is checked under the publication lock.
CREATE TABLE content_intake.commit_ticket_sources (
  ticket_hash content_intake.sha256 NOT NULL REFERENCES content_intake.commit_tickets,
  source_id content_intake.identifier NOT NULL REFERENCES content_intake.sources,
  source_generation content_intake.generation NOT NULL,
  mode_version content_intake.version NOT NULL,
  source_evidence_generation content_intake.generation NOT NULL,
  PRIMARY KEY (ticket_hash,source_id)
);

-- One catalog per existing release; there is no is_current/current_release column here.
-- Material remains in immutable candidate versions; inherited source versions retain
-- their approval lineage and vocabulary display versions. P2 SOP/media are actual empty arrays.
CREATE TABLE content_intake.release_catalogs (
  release_id TEXT PRIMARY KEY REFERENCES public.content_releases,
  format_version TEXT NOT NULL CHECK (format_version='intake-v2.1'),
  sop_nodes JSONB NOT NULL DEFAULT '[]' CHECK (sop_nodes='[]'::jsonb),
  sop_edges JSONB NOT NULL DEFAULT '[]' CHECK (sop_edges='[]'::jsonb),
  media JSONB NOT NULL DEFAULT '[]' CHECK (media='[]'::jsonb)
);
CREATE TABLE content_intake.release_lineage (
  release_id TEXT NOT NULL REFERENCES content_intake.release_catalogs,
  source_id content_intake.identifier NOT NULL,
  business_entry_id content_intake.identifier NOT NULL,
  script_version content_intake.version NOT NULL,
  candidate_id content_intake.identifier NOT NULL,
  candidate_version content_intake.version NOT NULL,
  review_request_id content_intake.identifier NOT NULL REFERENCES content_intake.review_bindings,
  content_valid_until TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (release_id,source_id,business_entry_id),
  FOREIGN KEY (candidate_id,candidate_version,source_id) REFERENCES content_intake.candidate_versions(candidate_id,version,source_id),
  FOREIGN KEY (review_request_id,candidate_id,candidate_version) REFERENCES content_intake.review_bindings(review_request_id,candidate_id,candidate_version)
);
CREATE INDEX release_lineage_review ON content_intake.release_lineage(review_request_id,release_id);
CREATE TABLE content_intake.release_revocations (
  release_id TEXT PRIMARY KEY REFERENCES public.content_releases,
  generation content_intake.version NOT NULL,
  reason TEXT NOT NULL CHECK (length(btrim(reason)) BETWEEN 1 AND 512),
  revoked_at TIMESTAMPTZ NOT NULL
);
ALTER TABLE public.snapshot_offline_leases ADD CONSTRAINT lease_principal_release_identity UNIQUE (lease_token_hash,user_id,release_id);
CREATE TABLE content_intake.entitlements (
  entitlement_hash content_intake.sha256 PRIMARY KEY,
  principal_id content_intake.identifier NOT NULL,
  user_id TEXT NOT NULL,
  lease_token_hash TEXT NOT NULL UNIQUE REFERENCES public.snapshot_offline_leases,
  release_id TEXT NOT NULL REFERENCES content_intake.release_catalogs,
  shop_id content_intake.identifier NOT NULL,
  context_generation content_intake.version NOT NULL,
  principal_generation content_intake.generation NOT NULL,
  release_generation content_intake.generation NOT NULL,
  issued_at TIMESTAMPTZ NOT NULL CHECK (isfinite(issued_at)),
  valid_until TIMESTAMPTZ NOT NULL,
  FOREIGN KEY (principal_id,user_id) REFERENCES content_intake.principals(principal_id,user_id),
  FOREIGN KEY (lease_token_hash,user_id,release_id) REFERENCES public.snapshot_offline_leases(lease_token_hash,user_id,release_id),
  CHECK (valid_until>issued_at AND valid_until<=issued_at+INTERVAL '5 minutes')
);
CREATE TABLE content_intake.entitlement_scopes (
  entitlement_hash content_intake.sha256 NOT NULL REFERENCES content_intake.entitlements,
  source_id content_intake.identifier NOT NULL REFERENCES content_intake.sources,
  PRIMARY KEY (entitlement_hash,source_id)
);

CREATE FUNCTION content_intake.immutable_history() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='INTAKE_HISTORY_IMMUTABLE';
END;
$$;
CREATE FUNCTION content_intake.candidate_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='CANDIDATE_IMMUTABLE';
  END IF;
  IF (to_jsonb(NEW)-ARRAY['state','source_evidence_version','approval_evidence_version','revocation_generation','updated_at','digest'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','source_evidence_version','approval_evidence_version','revocation_generation','updated_at','digest']) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='MATERIAL_CHANGED';
  END IF;
  IF NEW.source_evidence_version<OLD.source_evidence_version OR NEW.approval_evidence_version<OLD.approval_evidence_version
    OR NEW.revocation_generation<OLD.revocation_generation OR NEW.updated_at<OLD.updated_at THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='VERSION_REGRESSION';
  END IF;
  IF NEW.state<>OLD.state AND NOT (
    (OLD.state='awaiting-evidence' AND NEW.state IN ('ready','cancelled','invalidated')) OR
    (OLD.state='ready' AND NEW.state IN ('awaiting-evidence','publishing','cancelled','invalidated')) OR
    (OLD.state='publishing' AND NEW.state IN ('awaiting-evidence','ready','published','cancelled','invalidated'))
  ) THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='CANDIDATE_STATE_TRANSITION'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER candidate_immutable BEFORE UPDATE OR DELETE ON content_intake.candidate_versions
  FOR EACH ROW EXECUTE FUNCTION content_intake.candidate_guard();
CREATE FUNCTION content_intake.candidate_scope_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
DECLARE s content_intake.scopes; p content_intake.principals;
BEGIN
  IF NEW.state<>'awaiting-evidence' OR NEW.source_evidence_version<>0 OR NEW.approval_evidence_version<>0 OR NEW.revocation_generation<>0 THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='CANDIDATE_INITIAL_STATE';
  END IF;
  SELECT * INTO STRICT s FROM content_intake.scopes WHERE scope_id=NEW.scope_id;
  SELECT * INTO STRICT p FROM content_intake.principals WHERE principal_id=NEW.actor_id;
  IF p.tenant_id<>s.tenant_id OR p.app_id<>s.app_id OR
    NEW.material->'scope' IS DISTINCT FROM jsonb_build_object('tenantId',s.tenant_id,'appId',s.app_id,'brandId',s.brand_id,'shopId',s.shop_id,'domain',s.domain,'sourceId',NEW.source_id) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='SOURCE_SCOPE_MISMATCH';
  END IF;
  IF NOT (NEW.material->'contributors' ? NEW.actor_id::text)
    OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(NEW.material->'contributors'))
    OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(NEW.material->'contributors') c(value)
      WHERE NOT EXISTS (SELECT 1 FROM content_intake.principals cp WHERE cp.principal_id=c.value AND cp.tenant_id=p.tenant_id AND cp.app_id=p.app_id)) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='CONTRIBUTOR_BINDING';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER candidate_scope BEFORE INSERT ON content_intake.candidate_versions FOR EACH ROW EXECUTE FUNCTION content_intake.candidate_scope_guard();
CREATE FUNCTION content_intake.source_scope_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF NEW.source_id<>OLD.source_id OR NEW.scope_id<>OLD.scope_id THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='SOURCE_SCOPE_IMMUTABLE';
  END IF;
  IF NEW.current_mapping_version<OLD.current_mapping_version OR NEW.mode_version<OLD.mode_version OR NEW.revocation_generation<OLD.revocation_generation
    OR (NEW.mode<>OLD.mode AND NEW.mode_version<=OLD.mode_version) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='VERSION_REGRESSION';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER source_scope BEFORE UPDATE ON content_intake.sources FOR EACH ROW EXECUTE FUNCTION content_intake.source_scope_guard();
CREATE FUNCTION content_intake.review_binding_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['instance_code','attachment_file_code']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['instance_code','attachment_file_code'])
    OR (OLD.instance_code IS NOT NULL AND OLD.instance_code IS DISTINCT FROM NEW.instance_code)
    OR (OLD.attachment_file_code IS NOT NULL AND OLD.attachment_file_code IS DISTINCT FROM NEW.attachment_file_code) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='APPROVAL_BINDING_IMMUTABLE';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER review_binding_immutable BEFORE UPDATE OR DELETE ON content_intake.review_bindings FOR EACH ROW EXECUTE FUNCTION content_intake.review_binding_guard();
CREATE FUNCTION content_intake.vocabulary_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF NEW.vocabulary_id<>OLD.vocabulary_id OR NEW.kind<>OLD.kind OR NEW.scope_id<>OLD.scope_id OR NEW.meaning_digest<>OLD.meaning_digest THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='MEANING_CHANGED';
  END IF;
  IF NOT NEW.active AND EXISTS (SELECT 1 FROM content_intake.candidate_vocabulary WHERE vocabulary_id=OLD.vocabulary_id) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='VOCABULARY_IN_USE';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER vocabulary_semantics BEFORE UPDATE ON content_intake.vocabulary
  FOR EACH ROW EXECUTE FUNCTION content_intake.vocabulary_guard();
CREATE FUNCTION content_intake.principal_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['current_facts_version','revocation_generation']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['current_facts_version','revocation_generation']) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='IDENTITY_IMMUTABLE';
  END IF;
  IF NEW.current_facts_version<OLD.current_facts_version OR NEW.revocation_generation<OLD.revocation_generation THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='VERSION_REGRESSION';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER principal_version BEFORE UPDATE OR DELETE ON content_intake.principals FOR EACH ROW EXECUTE FUNCTION content_intake.principal_guard();
CREATE FUNCTION content_intake.approval_current_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE previous content_intake.approval_facts; next_facts content_intake.approval_facts;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='APPROVAL_POINTER_IMMUTABLE'; END IF;
  SELECT * INTO STRICT next_facts FROM content_intake.approval_facts WHERE review_request_id=NEW.review_request_id AND facts_version=NEW.facts_version;
  IF TG_OP='UPDATE' THEN
    SELECT * INTO STRICT previous FROM content_intake.approval_facts WHERE review_request_id=OLD.review_request_id AND facts_version=OLD.facts_version;
    IF NEW.review_request_id<>OLD.review_request_id OR NEW.facts_version<OLD.facts_version OR next_facts.revocation_generation<previous.revocation_generation
      OR (previous.state='revoked' AND next_facts.state<>'revoked') THEN
      RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='APPROVAL_VERSION_REGRESSION';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER approval_pointer BEFORE UPDATE OR DELETE ON content_intake.approval_current FOR EACH ROW EXECUTE FUNCTION content_intake.approval_current_guard();
CREATE FUNCTION content_intake.grant_parent_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE parent content_intake.grants;
BEGIN
  IF NEW.parent_grant_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO STRICT parent FROM content_intake.grants WHERE grant_id=NEW.parent_grant_id;
  IF parent.recipient_id<>NEW.issuer_id OR parent.tenant_id<>NEW.tenant_id OR parent.app_id<>NEW.app_id OR parent.scope_id<>NEW.scope_id
    OR parent.action<>NEW.action OR (parent.source_id IS NOT NULL AND parent.source_id IS DISTINCT FROM NEW.source_id)
    OR parent.starts_at>NEW.starts_at OR parent.expires_at<NEW.expires_at OR parent.revoked_at IS NOT NULL
    OR NOT ((NEW.kind='business' AND parent.kind IN ('allocation','delegation')) OR (NEW.kind='delegation' AND parent.kind='allocation')) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='GRANT_PARENT_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER grant_parent BEFORE INSERT ON content_intake.grants FOR EACH ROW EXECUTE FUNCTION content_intake.grant_parent_guard();
CREATE FUNCTION content_intake.object_scope_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NEW.source_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM content_intake.sources src JOIN content_intake.scopes s USING(scope_id)
    WHERE src.source_id=NEW.source_id AND s.tenant_id=NEW.tenant_id AND s.app_id=NEW.app_id
  ) THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='OBJECT_SCOPE_MISMATCH'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER object_scope BEFORE INSERT ON content_intake.objects FOR EACH ROW EXECUTE FUNCTION content_intake.object_scope_guard();
CREATE FUNCTION content_intake.parse_object_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='PARSE_BINDING_IMMUTABLE'; END IF;
  IF NOT EXISTS (SELECT 1 FROM content_intake.objects WHERE object_id=NEW.object_id AND source_id=NEW.source_id AND actor_id=NEW.actor_id AND purpose='input')
    OR (NEW.report_object_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM content_intake.objects WHERE object_id=NEW.report_object_id AND source_id=NEW.source_id AND actor_id=NEW.actor_id AND purpose='report')) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='OBJECT_BINDING';
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['state','report_object_id','finished_at','result_candidate_id','result_candidate_version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','report_object_id','finished_at','result_candidate_id','result_candidate_version']) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='PARSE_BINDING_IMMUTABLE';
  END IF;
  IF NOT (NEW.actor_id=ANY(NEW.contributor_ids))
    OR cardinality(NEW.contributor_ids)<>(SELECT count(DISTINCT v) FROM unnest(NEW.contributor_ids) v)
    OR EXISTS (SELECT 1 FROM unnest(NEW.contributor_ids) c(id) WHERE NOT EXISTS (
      SELECT 1 FROM content_intake.principals p JOIN content_intake.principals actor ON actor.principal_id=NEW.actor_id
      WHERE p.principal_id=c.id AND p.tenant_id=actor.tenant_id AND p.app_id=actor.app_id)) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='PARSE_CONTRIBUTOR_BINDING';
  END IF;
  IF NEW.result_candidate_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM content_intake.candidate_versions c WHERE c.candidate_id=NEW.result_candidate_id AND c.version=NEW.result_candidate_version
      AND c.source_version=NEW.source_version AND c.actor_id=NEW.actor_id
      AND (SELECT array_agg(value ORDER BY value) FROM jsonb_array_elements_text(c.material->'contributors'))=
          (SELECT array_agg(v::text ORDER BY v::text) FROM unnest(NEW.contributor_ids) v)
  ) THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='PARSE_RESULT_BINDING'; END IF;
  IF NEW.result_candidate_id IS NOT NULL AND ((NEW.expected_prior_id IS NULL AND NEW.result_candidate_version<>1)
    OR (NEW.expected_prior_id IS NOT NULL AND (NEW.result_candidate_id<>NEW.expected_prior_id OR NEW.result_candidate_version<>NEW.expected_prior_version+1))) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='PARSE_REVISION_BINDING';
  END IF;
  IF (TG_OP='INSERT' AND NEW.state<>'reading') OR (TG_OP='UPDATE' AND NEW.state<>OLD.state AND NOT (
    (OLD.state='reading' AND NEW.state IN ('parsing','failed','cancelled')) OR
    (OLD.state='parsing' AND NEW.state IN ('validated','failed','cancelled'))
  )) OR (TG_OP='UPDATE' AND OLD.state IN ('validated','failed','cancelled') AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='PARSE_STATE_TRANSITION';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER parse_object BEFORE INSERT OR UPDATE OR DELETE ON content_intake.parse_jobs FOR EACH ROW EXECUTE FUNCTION content_intake.parse_object_guard();
CREATE FUNCTION content_intake.vocabulary_scope_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM content_intake.candidate_versions c JOIN content_intake.scopes cs ON cs.scope_id=c.scope_id
    JOIN content_intake.vocabulary v ON v.vocabulary_id=NEW.vocabulary_id JOIN content_intake.scopes vs ON vs.scope_id=v.scope_id
    WHERE c.candidate_id=NEW.candidate_id AND c.version=NEW.candidate_version AND v.active
      AND (vs.tenant_id,vs.app_id,vs.brand_id,vs.domain)=(cs.tenant_id,cs.app_id,cs.brand_id,cs.domain)
      AND (vs.shop_id IS NULL OR vs.shop_id IS NOT DISTINCT FROM cs.shop_id)
  ) THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='VOCABULARY_SCOPE'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER vocabulary_scope BEFORE INSERT ON content_intake.candidate_vocabulary FOR EACH ROW EXECUTE FUNCTION content_intake.vocabulary_scope_guard();
CREATE FUNCTION content_intake.review_package_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE obj content_intake.objects;
BEGIN
  SELECT * INTO STRICT obj FROM content_intake.objects WHERE object_id=NEW.package_object_id;
  IF obj.purpose<>'review-package' OR obj.sha256<>NEW.package_sha256 OR obj.tenant_id<>NEW.tenant_id OR obj.app_id<>NEW.app_id THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='REVIEW_PACKAGE_BINDING';
  END IF;
  IF NEW.candidate_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM content_intake.candidate_versions c WHERE c.candidate_id=NEW.candidate_id AND c.version=NEW.candidate_version AND c.source_id=obj.source_id) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='REVIEW_PACKAGE_SOURCE';
  END IF;
  IF NEW.rollback_plan_id IS NOT NULL AND (obj.source_id IS NOT NULL OR NOT EXISTS (
    SELECT 1 FROM content_intake.rollback_plans r JOIN content_intake.principals p ON p.principal_id=r.actor_id
    WHERE r.rollback_plan_id=NEW.rollback_plan_id AND p.tenant_id=NEW.tenant_id AND p.app_id=NEW.app_id
  )) THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='REVIEW_PACKAGE_ROLLBACK'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER review_package BEFORE INSERT ON content_intake.review_bindings FOR EACH ROW EXECUTE FUNCTION content_intake.review_package_guard();
CREATE FUNCTION content_intake.approval_package_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NEW.state='approved' AND NOT EXISTS (SELECT 1 FROM content_intake.review_bindings WHERE review_request_id=NEW.review_request_id AND package_sha256=NEW.package_verified_sha256 AND instance_code IS NOT NULL AND attachment_file_code IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='APPROVAL_PACKAGE_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER approval_package BEFORE INSERT ON content_intake.approval_facts FOR EACH ROW EXECUTE FUNCTION content_intake.approval_package_guard();
CREATE FUNCTION content_intake.write_attempt_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='OPERATION_IMMUTABLE'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.state<>'pending' THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='OPERATION_INITIAL_STATE'; END IF;
  ELSE
    IF (to_jsonb(NEW)-ARRAY['state','import_batch_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','import_batch_id'])
      OR (OLD.import_batch_id IS NOT NULL AND OLD.import_batch_id IS DISTINCT FROM NEW.import_batch_id) THEN
      RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='OPERATION_IMMUTABLE';
    END IF;
    IF NEW.state<>OLD.state AND NOT ((OLD.state='pending' AND NEW.state IN ('unknown','published','cancelled','failed')) OR (OLD.state='unknown' AND NEW.state IN ('published','cancelled','failed'))) THEN
      RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='OPERATION_STATE_TRANSITION';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER write_attempt BEFORE INSERT OR UPDATE OR DELETE ON content_intake.write_attempts FOR EACH ROW EXECUTE FUNCTION content_intake.write_attempt_guard();
CREATE FUNCTION content_intake.ticket_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.consumed_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='TICKET_INITIAL_STATE'; END IF;
  ELSIF TG_OP='DELETE' OR (to_jsonb(NEW)-'consumed_at') IS DISTINCT FROM (to_jsonb(OLD)-'consumed_at')
    OR OLD.consumed_at IS NOT NULL OR NEW.consumed_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='TICKET_IMMUTABLE_OR_CONSUMED';
  ELSIF clock_timestamp()<NEW.issued_at OR clock_timestamp()>=NEW.expires_at OR NEW.consumed_at>clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='TICKET_EXPIRED';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER ticket_once BEFORE INSERT OR UPDATE OR DELETE ON content_intake.commit_tickets FOR EACH ROW EXECUTE FUNCTION content_intake.ticket_guard();
CREATE FUNCTION content_intake.entitlement_lease_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.snapshot_offline_leases WHERE lease_token_hash=NEW.lease_token_hash AND user_id=NEW.user_id AND release_id=NEW.release_id AND NEW.issued_at>=issued_at AND NEW.valid_until<=expires_at) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='ENTITLEMENT_LEASE_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER entitlement_lease BEFORE INSERT ON content_intake.entitlements FOR EACH ROW EXECUTE FUNCTION content_intake.entitlement_lease_guard();
DO $$
DECLARE relation TEXT;
BEGIN
  FOREACH relation IN ARRAY ARRAY['scopes','grant_history','role_rule_history','principal_facts','source_mappings','vocabulary_displays','objects',
    'candidate_vocabulary','commit_ticket_sources','source_confirmations','approval_facts','publications','rollback_plans','rollback_scopes','release_catalogs','release_lineage','release_revocations','entitlements','entitlement_scopes'] LOOP
    EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON content_intake.%I FOR EACH ROW EXECUTE FUNCTION content_intake.immutable_history()',relation);
  END LOOP;
END;
$$;
-- No application role can write half a protocol. The candidate is intentionally sealed
-- until product-side transactions, legacy-write fencing and read gates pass intake tests.
REVOKE ALL ON ALL TABLES IN SCHEMA content_intake FROM PUBLIC,app_runtime,app_content_admin,app_import_worker,app_backend_auth,app_backend_review,app_backend_worker;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA content_intake FROM PUBLIC,app_runtime,app_content_admin,app_import_worker,app_backend_auth,app_backend_review,app_backend_worker;
COMMENT ON SCHEMA content_intake IS 'P2 CANDIDATE; storage constraints only; no application grants; runtime/activation/production NOT_CERTIFIED';
COMMIT;
-- END CONTENT INTAKE

-- BEGIN INTAKE USAGE 44b724f27c5f6c6b91d18c4eb81cae0226a112e88744f595ae255ca2115885e0
-- DRAFT: additive usage-context storage; no application ACL or runtime activation.
BEGIN;
-- Stored selections have one canonical form, so request order cannot change a lease.
CREATE FUNCTION content_intake.selection_ids_valid(ids TEXT[]) RETURNS BOOLEAN
LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$
  SELECT ids IS NOT NULL AND cardinality(ids)<=100 AND (cardinality(ids)=0 OR
    (array_ndims(ids)=1 AND array_lower(ids,1)=1 AND array_position(ids,NULL) IS NULL
     AND NOT EXISTS (SELECT 1 FROM unnest(ids) id WHERE id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$')
     AND ids=ARRAY(SELECT DISTINCT id COLLATE "C" FROM unnest(ids) id ORDER BY id COLLATE "C")))
$$;
CREATE TABLE content_intake.entitlement_contexts (
  entitlement_hash content_intake.sha256 PRIMARY KEY REFERENCES content_intake.entitlements,
  session_token_hash content_intake.sha256 NOT NULL,
  product_ids TEXT[] NOT NULL CHECK (content_intake.selection_ids_valid(product_ids)),
  scenario_ids TEXT[] NOT NULL CHECK (content_intake.selection_ids_valid(scenario_ids))
);
-- No FK to the short-lived sessions table: logout/retention may remove sessions.
-- Creation checks its identity/deadline; every read must join the live session again.
-- The private stored hash is obtained by authentication and never returned on the wire.
CREATE FUNCTION content_intake.entitlement_context_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM content_intake.entitlements e
    JOIN backend_identity.sessions s ON s.token_hash=NEW.session_token_hash
    JOIN backend_identity.subject_bindings b ON b.binding_id=s.binding_id AND b.user_id=e.user_id
    WHERE e.entitlement_hash=NEW.entitlement_hash AND b.enabled AND s.revoked_at IS NULL
      AND s.issued_at<=e.issued_at AND e.issued_at<=clock_timestamp()
      AND e.valid_until<=s.expires_at AND clock_timestamp()<e.valid_until
    FOR SHARE OF s,b
  ) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003',MESSAGE='ENTITLEMENT_SESSION_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER entitlement_context_binding BEFORE INSERT ON content_intake.entitlement_contexts
  FOR EACH ROW EXECUTE FUNCTION content_intake.entitlement_context_guard();
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON content_intake.entitlement_contexts
  FOR EACH ROW EXECUTE FUNCTION content_intake.immutable_history();
-- Existing rows are not backfilled with invented sessions/selections. They are
-- unreadable in the new API. Every NEW qualification must commit with its context.
CREATE FUNCTION content_intake.entitlement_context_required() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM content_intake.entitlement_contexts WHERE entitlement_hash=NEW.entitlement_hash) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003',MESSAGE='ENTITLEMENT_CONTEXT_REQUIRED';
  END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER entitlement_context_required AFTER INSERT ON content_intake.entitlements
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION content_intake.entitlement_context_required();
REVOKE ALL ON TABLE content_intake.entitlement_contexts FROM PUBLIC,app_runtime,app_content_admin,app_import_worker,app_backend_auth,app_backend_review,app_backend_worker;
REVOKE ALL ON FUNCTION content_intake.selection_ids_valid(TEXT[]),content_intake.entitlement_context_guard(),content_intake.entitlement_context_required()
  FROM PUBLIC,app_runtime,app_content_admin,app_import_worker,app_backend_auth,app_backend_review,app_backend_worker;
COMMIT;
-- END INTAKE USAGE

-- BEGIN INTAKE DIRECT 12d72d6700e97e1fd6931d1e430aad48e23ee2263b4b7fc849a27fb26f3e576c
-- DRAFT direct-publication storage. Existing rows retain approval-v1 forever.
-- No application grants or runtime activation; product transaction/reader overlays
-- must be upgraded together before direct-v1 can be used.
SET search_path = public, pg_catalog;
ALTER TABLE content_intake.candidate_versions
  ADD COLUMN publication_policy TEXT NOT NULL DEFAULT 'approval-v1'
    CHECK (publication_policy IN ('approval-v1','direct-v1')),
  ADD UNIQUE(candidate_id,version,publication_policy);
ALTER TABLE content_intake.write_attempts
  ADD COLUMN publication_policy TEXT NOT NULL DEFAULT 'approval-v1'
    CHECK (publication_policy IN ('approval-v1','direct-v1')),
  ADD UNIQUE(actor_id,action,operation_id,publication_policy),
  ADD FOREIGN KEY(candidate_id,candidate_version,publication_policy)
    REFERENCES content_intake.candidate_versions(candidate_id,version,publication_policy);
-- The frozen predecessor used unnamed constraints. Resolve the unique approval
-- gate by its definition and fail closed if the predecessor no longer matches.
DO $$
DECLARE t TEXT; names TEXT[];
BEGIN
  FOREACH t IN ARRAY ARRAY['candidate_versions','write_attempts'] LOOP
    SELECT array_agg(conname) INTO names FROM pg_constraint
      WHERE conrelid=format('content_intake.%I',t)::regclass AND contype='c'
        AND pg_get_constraintdef(oid) LIKE '%approval_evidence_version%';
    IF cardinality(names) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Unexpected predecessor approval constraint: %',t; END IF;
    EXECUTE format('ALTER TABLE content_intake.%I DROP CONSTRAINT %I',t,names[1]);
  END LOOP;
END;
$$;
ALTER TABLE content_intake.candidate_versions
  ADD CONSTRAINT candidate_publication_readiness CHECK (
    (publication_policy<>'direct-v1' OR approval_evidence_version=0)
    AND (state NOT IN ('ready','publishing','published') OR
      (source_evidence_version>0 AND (publication_policy='direct-v1' OR approval_evidence_version>0))));
ALTER TABLE content_intake.write_attempts
  ADD CONSTRAINT attempt_publication_evidence CHECK (
    (action='cancel' AND source_evidence_version IS NULL AND approval_evidence_version IS NULL AND import_batch_id IS NULL)
    OR (action IN ('publish','rollback')
      AND ((action='publish' AND source_evidence_version IS NOT NULL)
        OR (action='rollback' AND source_evidence_version IS NULL AND import_batch_id IS NULL))
      AND ((publication_policy='approval-v1' AND approval_evidence_version IS NOT NULL)
        OR (publication_policy='direct-v1' AND approval_evidence_version IS NULL))));
ALTER TABLE content_intake.commit_tickets
  ADD COLUMN publication_policy TEXT NOT NULL DEFAULT 'approval-v1'
    CHECK (publication_policy IN ('approval-v1','direct-v1')),
  ALTER COLUMN reviewer_facts_version DROP NOT NULL,
  ALTER COLUMN reviewer_generation DROP NOT NULL,
  ALTER COLUMN approval_facts_version DROP NOT NULL,
  ALTER COLUMN approval_generation DROP NOT NULL,
  ADD FOREIGN KEY(actor_id,action,operation_id,publication_policy)
    REFERENCES content_intake.write_attempts(actor_id,action,operation_id,publication_policy),
  ADD CONSTRAINT ticket_publication_evidence CHECK (
    (publication_policy='approval-v1' AND reviewer_facts_version IS NOT NULL AND reviewer_generation IS NOT NULL
      AND approval_facts_version IS NOT NULL AND approval_generation IS NOT NULL)
    OR (publication_policy='direct-v1' AND reviewer_facts_version IS NULL AND reviewer_generation IS NULL
      AND approval_facts_version IS NULL AND approval_generation IS NULL));
ALTER TABLE content_intake.publications
  ADD COLUMN publication_policy TEXT NOT NULL DEFAULT 'approval-v1'
    CHECK (publication_policy IN ('approval-v1','direct-v1')),
  ADD COLUMN confirmed_at TIMESTAMPTZ,
  ADD FOREIGN KEY(actor_id,action,operation_id,publication_policy)
    REFERENCES content_intake.write_attempts(actor_id,action,operation_id,publication_policy),
  ADD FOREIGN KEY(candidate_id,candidate_version,publication_policy)
    REFERENCES content_intake.candidate_versions(candidate_id,version,publication_policy),
  ADD CONSTRAINT publication_confirmation CHECK (
    (publication_policy='approval-v1' AND confirmed_at IS NULL)
    OR (publication_policy='direct-v1' AND confirmed_at IS NOT NULL AND isfinite(confirmed_at)));
ALTER TABLE content_intake.release_lineage
  ADD COLUMN publication_policy TEXT NOT NULL DEFAULT 'approval-v1'
    CHECK (publication_policy IN ('approval-v1','direct-v1')),
  ALTER COLUMN review_request_id DROP NOT NULL,
  ADD FOREIGN KEY(candidate_id,candidate_version,publication_policy)
    REFERENCES content_intake.candidate_versions(candidate_id,version,publication_policy),
  ADD CONSTRAINT lineage_publication_evidence CHECK (
    (publication_policy='approval-v1' AND review_request_id IS NOT NULL)
    OR (publication_policy='direct-v1' AND review_request_id IS NULL));
-- Existing candidate/attempt/publication/lineage mutation guards include these
-- new columns in their immutable projections. No historical policy is rewritten.
RESET search_path;

-- 不删除历史 grant。enabler/agent 的旧非 query 授权不再放行新业务操作。
-- 本函数不授予应用角色，也不证明分配凭证。旧 grant 与旧 approval-v1 行不改写成 direct-v1。
-- 分配谓词没有对应函数：不在这里新造，也不新增审批表。兼容规则见 17 号规范。
CREATE OR REPLACE FUNCTION content_intake.authorization_deadline(
  p_principal TEXT, p_action TEXT, p_scope TEXT, p_source TEXT, p_at TIMESTAMPTZ
) RETURNS TIMESTAMPTZ LANGUAGE SQL STABLE SET search_path = pg_catalog AS $$
  SELECT least(f.valid_until,max(g.expires_at))
  FROM content_intake.principals p
  JOIN content_intake.principal_facts f ON f.principal_id=p.principal_id AND f.facts_version=p.current_facts_version
  JOIN content_intake.scopes s ON s.scope_id=p_scope AND s.tenant_id=p.tenant_id AND s.app_id=p.app_id
  JOIN content_intake.grants g ON g.recipient_id=p.principal_id AND g.scope_id=s.scope_id
    AND g.action=p_action AND g.kind='business' AND g.revoked_at IS NULL
    AND (g.source_id IS NULL OR g.source_id=p_source) AND g.starts_at<=p_at AND p_at<g.expires_at
  JOIN content_intake.role_rules r ON r.tenant_id=p.tenant_id AND r.app_id=p.app_id
    AND r.department_id=ANY(f.department_ids) AND r.job_id=f.job_id
  WHERE p.principal_id=p_principal AND f.enabled AND f.checked_at<=p_at AND p_at<f.valid_until
    AND EXISTS (SELECT 1 FROM content_intake.sources src WHERE src.source_id=p_source AND src.scope_id=s.scope_id)
  GROUP BY f.valid_until
  HAVING count(DISTINCT r.role)=1
    AND (min(r.role) IN ('director','manager','supervisor','lead')
      OR (min(r.role) IN ('agent','enabler') AND p_action='query'))
$$;
-- END INTAKE DIRECT

-- BEGIN INTAKE RUNTIME ROLES 54a7a75d8b58f0217cdbc782b450ffc0f256633cb050a509fb930274e17fb9ee
-- DRAFT capability bootstrap. No environment LOGIN, password, role membership or database CONNECT.
-- Installer is the governance migration owner; existing same-name roles fail closed.
CREATE ROLE intake_runtime_fn_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
CREATE ROLE intake_usage NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
CREATE ROLE intake_business NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
CREATE ROLE intake_worker NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
CREATE ROLE intake_org_writer NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
CREATE ROLE intake_directory_fn_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
CREATE ROLE intake_directory_key_operator NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS NOREPLICATION;
-- END INTAKE RUNTIME ROLES

-- BEGIN INTAKE RUNTIME ORGANIZATION 656113a5b12a5f6438df467e1afe5858b26c60062568cec4c4535069a283ca14
-- DRAFT registered organization input. Trusted service owns canonical request digests and facts CAS.
CREATE SCHEMA intake_organization;
REVOKE ALL ON SCHEMA intake_organization FROM PUBLIC;
CREATE TABLE intake_organization.bindings (
  tenant_id content_intake.identifier NOT NULL, app_id content_intake.identifier NOT NULL, principal_id content_intake.identifier NOT NULL,
  binding_version content_intake.version NOT NULL, binding_digest content_intake.sha256 NOT NULL,
  open_id content_intake.identifier NOT NULL, enabled boolean NOT NULL, valid_until timestamptz NOT NULL CHECK(isfinite(valid_until)),
  PRIMARY KEY(tenant_id,app_id,principal_id,binding_version),
  FOREIGN KEY(principal_id,tenant_id,app_id) REFERENCES content_intake.principals(principal_id,tenant_id,app_id),
  UNIQUE(tenant_id,app_id,principal_id,binding_version,open_id)
);
CREATE TABLE intake_organization.current_bindings (
  tenant_id content_intake.identifier NOT NULL, app_id content_intake.identifier NOT NULL, principal_id content_intake.identifier NOT NULL,
  binding_version content_intake.version NOT NULL, open_id content_intake.identifier NOT NULL,
  PRIMARY KEY(tenant_id,app_id,principal_id),
  UNIQUE(tenant_id,app_id,open_id),
  FOREIGN KEY(tenant_id,app_id,principal_id,binding_version,open_id)
    REFERENCES intake_organization.bindings(tenant_id,app_id,principal_id,binding_version,open_id)
);
CREATE TABLE intake_organization.observations (
  principal_id content_intake.identifier NOT NULL, facts_version content_intake.version NOT NULL,
  tenant_id content_intake.identifier NOT NULL, app_id content_intake.identifier NOT NULL, binding_version content_intake.version NOT NULL,
  request_digest content_intake.sha256 NOT NULL,
  kind text NOT NULL CHECK(kind IN ('observation','revocation')),
  mapping_version text, directory_digest content_intake.sha256, observed_until timestamptz CHECK(isfinite(observed_until)),
  PRIMARY KEY(principal_id,facts_version),
  FOREIGN KEY(principal_id,facts_version) REFERENCES content_intake.principal_facts,
  FOREIGN KEY(tenant_id,app_id,principal_id,binding_version) REFERENCES intake_organization.bindings,
  CHECK ((kind='observation' AND mapping_version IS NOT NULL AND mapping_version='feishu-contact-job-title-v1'
    AND directory_digest IS NOT NULL AND directory_digest ~ '^[0-9a-f]{64}$' AND observed_until IS NOT NULL)
    OR (kind='revocation' AND mapping_version IS NULL AND directory_digest IS NULL AND observed_until IS NULL))
);

-- The service owns observation mapping/digests, while SQL keeps append-only
-- history and current binding CAS. It never creates a principal or a grant.
CREATE FUNCTION intake_organization.history_immutable() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORGANIZATION_HISTORY_IMMUTABLE'; END;
$$;
CREATE TRIGGER organization_binding_immutable BEFORE UPDATE OR DELETE ON intake_organization.bindings
 FOR EACH ROW EXECUTE FUNCTION intake_organization.history_immutable();
CREATE TRIGGER organization_observation_immutable BEFORE UPDATE OR DELETE ON intake_organization.observations
 FOR EACH ROW EXECUTE FUNCTION intake_organization.history_immutable();
CREATE FUNCTION intake_organization.binding_transition() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE prior intake_organization.bindings;
BEGIN
  PERFORM backend_review.lock_content();
  SELECT b.* INTO prior FROM intake_organization.current_bindings c JOIN intake_organization.bindings b
   USING(tenant_id,app_id,principal_id,binding_version)
   WHERE c.tenant_id=NEW.tenant_id AND c.app_id=NEW.app_id AND c.principal_id=NEW.principal_id;
  IF NEW.binding_version<>coalesce(prior.binding_version,0)+1
    OR (coalesce(prior.enabled,false) AND (NEW.enabled OR NEW.open_id<>prior.open_id OR NEW.valid_until<>prior.valid_until))
    OR (NOT coalesce(prior.enabled,false) AND (NOT NEW.enabled OR NEW.valid_until<=clock_timestamp())) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003',MESSAGE='ORGANIZATION_BINDING_CONFLICT';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER organization_binding_transition BEFORE INSERT ON intake_organization.bindings
 FOR EACH ROW EXECUTE FUNCTION intake_organization.binding_transition();
CREATE FUNCTION intake_organization.current_binding_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND
    ((NEW.tenant_id,NEW.app_id,NEW.principal_id) IS DISTINCT FROM (OLD.tenant_id,OLD.app_id,OLD.principal_id)
      OR NEW.binding_version<>OLD.binding_version+1)) OR (TG_OP='INSERT' AND NEW.binding_version<>1 AND NOT EXISTS(
      SELECT 1 FROM intake_organization.current_bindings prior WHERE prior.tenant_id=NEW.tenant_id AND prior.app_id=NEW.app_id
        AND prior.principal_id=NEW.principal_id AND prior.binding_version+1=NEW.binding_version)) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003',MESSAGE='ORGANIZATION_BINDING_CONFLICT';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER organization_current_guard BEFORE INSERT OR UPDATE OR DELETE ON intake_organization.current_bindings
 FOR EACH ROW EXECUTE FUNCTION intake_organization.current_binding_guard();
CREATE FUNCTION intake_organization.observation_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE b intake_organization.bindings; c intake_organization.bindings; f content_intake.principal_facts;
BEGIN
  SELECT * INTO b FROM intake_organization.bindings WHERE tenant_id=NEW.tenant_id AND app_id=NEW.app_id
    AND principal_id=NEW.principal_id AND binding_version=NEW.binding_version;
  SELECT history.* INTO c FROM intake_organization.current_bindings ptr JOIN intake_organization.bindings history
    USING(tenant_id,app_id,principal_id,binding_version)
    WHERE ptr.tenant_id=NEW.tenant_id AND ptr.app_id=NEW.app_id AND ptr.principal_id=NEW.principal_id;
  SELECT * INTO f FROM content_intake.principal_facts WHERE principal_id=NEW.principal_id AND facts_version=NEW.facts_version;
  IF b.principal_id IS NULL OR c.principal_id IS NULL OR f.principal_id IS NULL OR NOT b.enabled
    OR (NEW.kind='observation' AND (NOT c.enabled OR c.binding_version<>b.binding_version
      OR f.valid_until>b.valid_until OR NEW.observed_until<f.checked_at OR NEW.observed_until>=f.valid_until
      OR NEW.observed_until>clock_timestamp() OR clock_timestamp()>=f.valid_until))
    OR (NEW.kind='revocation' AND (c.enabled OR c.binding_version<>b.binding_version+1 OR c.open_id<>b.open_id OR f.enabled)) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003',MESSAGE='ORGANIZATION_PROVENANCE_CONFLICT';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER organization_observation_guard BEFORE INSERT ON intake_organization.observations
 FOR EACH ROW EXECUTE FUNCTION intake_organization.observation_guard();
-- Registered writer facts require evidence in the SAME transaction. Bootstrap
-- fixtures remain separately privileged and do not masquerade as observations.
-- WHEN is captured when the row is inserted, not when deferred triggers run: a
-- later RESET ROLE cannot erase the evidence obligation.
CREATE FUNCTION intake_organization.fact_evidence_required() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM intake_organization.observations
    WHERE principal_id=NEW.principal_id AND facts_version=NEW.facts_version) THEN
    RAISE EXCEPTION USING ERRCODE='ZA003',MESSAGE='ORGANIZATION_PROVENANCE_REQUIRED';
  END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER organization_fact_evidence AFTER INSERT ON content_intake.principal_facts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (current_user='intake_org_writer')
 EXECUTE FUNCTION intake_organization.fact_evidence_required();
REVOKE ALL ON ALL TABLES IN SCHEMA intake_organization FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA intake_organization FROM PUBLIC;
-- END INTAKE RUNTIME ORGANIZATION

-- BEGIN INTAKE RUNTIME SESSION 4447e3d2a4477cd66aea754d2eb970d6e92f328c61192bb26edfc054d1768ac6
-- DRAFT trusted transaction boundary. Global content lock must precede this call.
CREATE SCHEMA intake_runtime;
REVOKE ALL ON SCHEMA intake_runtime FROM PUBLIC;

-- The caller supplies the authenticated module's private session hash and user,
-- never renderer data. No identity rows, token hashes or mutable capabilities are
-- returned. Locks remain held until the caller's transaction ends, serializing
-- session revocation and subject disable with its business transaction.
CREATE FUNCTION intake_runtime.lock_product_session(p_hash TEXT, p_user TEXT)
RETURNS TIMESTAMPTZ
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog
AS $$
DECLARE deadline TIMESTAMPTZ;
BEGIN
  IF p_hash IS NULL OR p_hash !~ '^[0-9a-f]{64}$'
    OR p_user IS NULL OR length(p_user) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='SESSION_UNAVAILABLE';
  END IF;
  SELECT s.expires_at INTO deadline
    FROM backend_identity.sessions s
    JOIN backend_identity.subject_bindings b USING(binding_id)
    WHERE s.token_hash=p_hash AND b.user_id=p_user AND b.enabled
      AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp()
    FOR SHARE OF s,b;
  -- Time can pass while waiting for a row lock. Do not return a stale deadline.
  IF deadline IS NULL OR deadline<=clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='ZA003', MESSAGE='SESSION_UNAVAILABLE';
  END IF;
  RETURN deadline;
END
$$;
REVOKE ALL ON FUNCTION intake_runtime.lock_product_session(TEXT,TEXT) FROM PUBLIC;

-- Startup/checkout guard for a dedicated environment LOGIN after SET ROLE.
-- session_user is the connection identity; current_user is exactly one NOLOGIN
-- capability. This is not an authenticated end-user or a complete ACL auditor.
CREATE FUNCTION intake_runtime.assert_purpose(p_purpose TEXT) RETURNS VOID
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE expected TEXT; login_record RECORD; capability_record RECORD;
BEGIN
  expected:=CASE p_purpose WHEN 'usage' THEN 'intake_usage' WHEN 'business' THEN 'intake_business'
    WHEN 'worker' THEN 'intake_worker' WHEN 'organization' THEN 'intake_org_writer'
    WHEN 'directory-key' THEN 'intake_directory_key_operator' ELSE NULL END;
  SELECT * INTO login_record FROM pg_roles WHERE rolname=session_user;
  SELECT * INTO capability_record FROM pg_roles WHERE rolname=expected;
  IF expected IS NULL OR current_user<>expected OR session_user=current_user
    OR NOT login_record.rolcanlogin OR login_record.rolinherit OR login_record.rolsuper OR login_record.rolcreatedb
    OR login_record.rolcreaterole OR login_record.rolbypassrls OR login_record.rolreplication
    OR capability_record.rolcanlogin OR capability_record.rolinherit OR capability_record.rolsuper
    OR capability_record.rolcreatedb OR capability_record.rolcreaterole OR capability_record.rolbypassrls OR capability_record.rolreplication
    OR NOT pg_has_role(session_user,expected,'MEMBER')
    OR EXISTS(SELECT 1 FROM pg_auth_members m WHERE m.member=login_record.oid
      AND (m.roleid<>capability_record.oid OR m.admin_option))
    OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=capability_record.oid)
    OR pg_has_role(session_user,'intake_runtime_fn_owner','MEMBER')
    OR pg_has_role(session_user,'intake_directory_fn_owner','MEMBER') THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='INTAKE_RUNTIME_ROLE_BOUNDARY';
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION intake_runtime.assert_purpose(TEXT) FROM PUBLIC;
GRANT USAGE ON SCHEMA intake_runtime TO intake_usage,intake_business,intake_worker,intake_org_writer,intake_directory_key_operator;
GRANT EXECUTE ON FUNCTION intake_runtime.assert_purpose(TEXT) TO intake_usage,intake_business,intake_worker,intake_org_writer,intake_directory_key_operator;
-- END INTAKE RUNTIME SESSION

-- BEGIN INTAKE SHOP DIRECTORY 73254ecac5144e7416e87177e1443944579cbc82ec93ed89273e98e4d1d5d9fc
-- Shop display directory. Names are not columns on sources and are not read from
-- Feishu contact fields. A registered steward row is the only writer. Absence of
-- that row fails closed. Writing a name does not insert a grant and does not
-- replace content_intake.authorization_deadline.
-- No application role receives EXECUTE or table privileges.

-- Match the wire character rule: no control/line-separator characters, and
-- ECMAScript whitespace may occur only inside a nonblank name.
CREATE FUNCTION content_intake.valid_shop_display_name(p_name TEXT) RETURNS BOOLEAN
LANGUAGE SQL IMMUTABLE SET search_path = pg_catalog AS $$
  SELECT p_name IS NOT NULL AND char_length(p_name) BETWEEN 1 AND 256
    AND p_name = btrim(p_name, U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
    AND p_name !~ U&'[\0001-\001F\007F\2028\2029]'
$$;

CREATE TABLE content_intake.shop_directory_stewards (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  steward_id content_intake.identifier,
  registered_at TIMESTAMPTZ NOT NULL CHECK (isfinite(registered_at)),
  version content_intake.version NOT NULL,
  active BOOLEAN NOT NULL,
  valid_until TIMESTAMPTZ,
  CHECK (active = (steward_id IS NOT NULL)),
  CHECK ((active AND valid_until IS NOT NULL AND isfinite(valid_until) AND registered_at < valid_until)
    OR (NOT active AND valid_until IS NULL)),
  PRIMARY KEY (tenant_id, app_id),
  FOREIGN KEY (steward_id, tenant_id, app_id)
    REFERENCES content_intake.principals(principal_id, tenant_id, app_id)
);
CREATE FUNCTION content_intake.shop_directory_steward_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP = 'DELETE' OR current_setting('content_intake.directory_steward_write',true) IS DISTINCT FROM 'writing' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  IF TG_OP = 'UPDATE' AND ((NEW.tenant_id,NEW.app_id) IS DISTINCT FROM (OLD.tenant_id,OLD.app_id)
      OR NEW.version <> OLD.version + 1) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CONFLICT';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER shop_directory_steward_immutable
  BEFORE INSERT OR UPDATE OR DELETE ON content_intake.shop_directory_stewards
  FOR EACH ROW EXECUTE FUNCTION content_intake.shop_directory_steward_guard();

CREATE TABLE content_intake.shop_directory_revisions (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  directory_revision content_intake.version NOT NULL,
  PRIMARY KEY (tenant_id, app_id)
);
CREATE TABLE content_intake.shop_displays (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  shop_id content_intake.identifier NOT NULL,
  display_version content_intake.version NOT NULL,
  display_name TEXT NOT NULL,
  directory_revision content_intake.version NOT NULL,
  steward_id content_intake.identifier NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL CHECK (isfinite(recorded_at)),
  PRIMARY KEY (tenant_id, app_id, shop_id, display_version),
  CHECK (content_intake.valid_shop_display_name(display_name)),
  FOREIGN KEY (steward_id, tenant_id, app_id)
    REFERENCES content_intake.principals(principal_id, tenant_id, app_id)
);
CREATE TABLE content_intake.shop_display_current (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  shop_id content_intake.identifier NOT NULL,
  display_version content_intake.version NOT NULL,
  directory_revision content_intake.version NOT NULL,
  PRIMARY KEY (tenant_id, app_id, shop_id),
  FOREIGN KEY (tenant_id, app_id, shop_id, display_version)
    REFERENCES content_intake.shop_displays(tenant_id, app_id, shop_id, display_version)
);

CREATE FUNCTION content_intake.shop_display_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DISPLAY_IMMUTABLE';
  END IF;
  IF pg_catalog.current_setting('content_intake.directory_write', true) IS DISTINCT FROM 'writing' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER shop_display_write
  BEFORE INSERT OR UPDATE OR DELETE ON content_intake.shop_displays
  FOR EACH ROW EXECUTE FUNCTION content_intake.shop_display_guard();

CREATE FUNCTION content_intake.shop_display_current_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DISPLAY_IMMUTABLE';
  END IF;
  IF pg_catalog.current_setting('content_intake.directory_write', true) IS DISTINCT FROM 'writing' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.tenant_id, NEW.app_id, NEW.shop_id) IS DISTINCT FROM (OLD.tenant_id, OLD.app_id, OLD.shop_id) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DISPLAY_IMMUTABLE';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER shop_display_current_write
  BEFORE INSERT OR UPDATE OR DELETE ON content_intake.shop_display_current
  FOR EACH ROW EXECUTE FUNCTION content_intake.shop_display_current_guard();

CREATE FUNCTION content_intake.shop_directory_revision_guard() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DISPLAY_IMMUTABLE';
  END IF;
  IF pg_catalog.current_setting('content_intake.directory_write', true) IS DISTINCT FROM 'writing' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.directory_revision IS DISTINCT FROM OLD.directory_revision + 1
      OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.app_id IS DISTINCT FROM OLD.app_id) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CONFLICT';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER shop_directory_revision_write
  BEFORE INSERT OR UPDATE OR DELETE ON content_intake.shop_directory_revisions
  FOR EACH ROW EXECUTE FUNCTION content_intake.shop_directory_revision_guard();

CREATE FUNCTION content_intake.upsert_shop_display(
  p_actor TEXT, p_tenant TEXT, p_app TEXT, p_shop TEXT, p_display_name TEXT, p_expected_revision BIGINT
) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog AS $$
DECLARE
  v_steward content_intake.identifier;
  v_steward_until TIMESTAMPTZ;
  v_revision content_intake.version;
  v_next_revision content_intake.version;
  v_version content_intake.version;
  v_identifier CONSTANT TEXT := '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$';
BEGIN
  IF p_actor IS NULL OR p_tenant IS NULL OR p_app IS NULL OR p_shop IS NULL
     OR p_actor !~ v_identifier OR p_tenant !~ v_identifier OR p_app !~ v_identifier OR p_shop !~ v_identifier
     OR NOT content_intake.valid_shop_display_name(p_display_name) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DISPLAY_INVALID';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_tenant || ':' || p_app, 0));
  SELECT s.steward_id, least(f.valid_until,s.valid_until) INTO v_steward, v_steward_until
  FROM content_intake.shop_directory_stewards s
  JOIN content_intake.principals p
    ON p.principal_id = p_actor AND p.tenant_id = s.tenant_id AND p.app_id = s.app_id
  JOIN content_intake.principal_facts f ON f.principal_id = p.principal_id AND f.facts_version = p.current_facts_version
  JOIN backend_identity.subject_bindings b ON b.user_id = p.user_id
  JOIN LATERAL (SELECT count(DISTINCT rr.role) AS n,min(rr.role) AS role FROM content_intake.role_rules rr
    WHERE rr.tenant_id=p.tenant_id AND rr.app_id=p.app_id AND rr.department_id=ANY(f.department_ids) AND rr.job_id=f.job_id) roles
    ON roles.n=1 AND roles.role IN ('director','manager')
  WHERE s.tenant_id = p_tenant AND s.app_id = p_app AND s.steward_id = p_actor
    AND s.active AND clock_timestamp() < s.valid_until
    AND b.enabled AND f.enabled AND f.checked_at <= pg_catalog.clock_timestamp()
    AND pg_catalog.clock_timestamp() < f.valid_until
  FOR SHARE OF s, p, f, b;
  IF NOT FOUND OR pg_catalog.clock_timestamp() >= v_steward_until THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  SELECT r.directory_revision INTO v_revision
  FROM content_intake.shop_directory_revisions r
  WHERE r.tenant_id = p_tenant AND r.app_id = p_app
  FOR UPDATE;
  IF NOT FOUND THEN
    IF p_expected_revision IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CONFLICT';
    END IF;
    v_next_revision := 1;
  ELSIF p_expected_revision IS DISTINCT FROM v_revision THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CONFLICT';
  ELSE
    v_next_revision := v_revision + 1;
  END IF;
  SELECT coalesce(max(d.display_version), 0) + 1 INTO v_version
  FROM content_intake.shop_displays d
  WHERE d.tenant_id = p_tenant AND d.app_id = p_app AND d.shop_id = p_shop;
  PERFORM pg_catalog.set_config('content_intake.directory_write', 'writing', true);
  INSERT INTO content_intake.shop_displays(
    tenant_id, app_id, shop_id, display_version, display_name, directory_revision, steward_id, recorded_at
  ) VALUES (
    p_tenant, p_app, p_shop, v_version, p_display_name, v_next_revision, p_actor, pg_catalog.clock_timestamp()
  );
  INSERT INTO content_intake.shop_display_current(tenant_id, app_id, shop_id, display_version, directory_revision)
  VALUES (p_tenant, p_app, p_shop, v_version, v_next_revision)
  ON CONFLICT (tenant_id, app_id, shop_id) DO UPDATE
    SET display_version = EXCLUDED.display_version,
        directory_revision = EXCLUDED.directory_revision;
  IF v_revision IS NULL THEN
    INSERT INTO content_intake.shop_directory_revisions(tenant_id, app_id, directory_revision)
    VALUES (p_tenant, p_app, v_next_revision);
  ELSE
    UPDATE content_intake.shop_directory_revisions
       SET directory_revision = v_next_revision
     WHERE tenant_id = p_tenant AND app_id = p_app;
  END IF;
  IF pg_catalog.clock_timestamp() >= v_steward_until THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  PERFORM pg_catalog.set_config('content_intake.directory_write', '', true);
  RETURN pg_catalog.jsonb_build_object(
    'shopId', p_shop,
    'displayName', p_display_name,
    'displayVersion', v_version,
    'directoryRevision', v_next_revision
  );
END;
$$;

-- Signing key is a distinct server-only input, never derived from a bearer token
-- or session hash. A client knowing its own token must not be able to sign a cursor.
CREATE FUNCTION content_intake.read_shop_directory(
  p_principal TEXT, p_session_hash TEXT, p_at TIMESTAMPTZ, p_cursor TEXT, p_limit INTEGER, p_cursor_signing_key TEXT, p_outer_deadline TIMESTAMPTZ DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog AS $$
DECLARE
  v_tenant content_intake.identifier;
  v_app content_intake.identifier;
  v_facts content_intake.version;
  v_revocation content_intake.generation;
  v_fact_until TIMESTAMPTZ;
  v_revision BIGINT := 0;
  v_digest TEXT;
  v_deadline TIMESTAMPTZ;
  v_count BIGINT;
  v_visible JSONB;
  v_limit INTEGER;
  v_cursor_ord BIGINT := 0;
  v_match TEXT[];
  v_cursor_signature TEXT;
  v_payload TEXT;
  v_signature TEXT;
  v_cursor_limit INTEGER;
  v_at TIMESTAMPTZ;
  v_cursor_facts BIGINT;
  v_cursor_revocation BIGINT;
  v_cursor_revision BIGINT;
  v_cursor_digest TEXT;
  v_cursor_deadline_us BIGINT;
  v_cursor_shop TEXT;
  v_boundary content_intake.identifier;
  v_items JSONB;
  v_len INTEGER;
  v_last TEXT;
  v_after_count BIGINT;
  v_deadline_us BIGINT;
  v_next TEXT;
BEGIN
  IF p_principal IS NULL OR p_session_hash IS NULL OR p_at IS NULL OR NOT isfinite(p_at)
     OR p_session_hash !~ '^[0-9a-f]{64}$'
     OR p_cursor_signing_key IS NULL OR p_cursor_signing_key !~ '^[0-9a-f]{64}$'
     OR (p_cursor IS NOT NULL AND (octet_length(p_cursor) = 0 OR octet_length(p_cursor) > 512))
     OR (p_limit IS NOT NULL AND (p_limit < 1 OR p_limit > 100)) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
  END IF;
  v_limit := coalesce(p_limit, 50);
  SELECT tenant_id, app_id INTO v_tenant, v_app FROM content_intake.principals WHERE principal_id = p_principal;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_SESSION';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended(v_tenant || ':' || v_app, 0));
  v_at := greatest(p_at, pg_catalog.clock_timestamp());
  SELECT p.current_facts_version, p.revocation_generation, f.valid_until
    INTO v_facts, v_revocation, v_fact_until
  FROM content_intake.principals p
  JOIN content_intake.principal_facts f
    ON f.principal_id = p.principal_id AND f.facts_version = p.current_facts_version
  JOIN backend_identity.subject_bindings b ON b.user_id = p.user_id
  WHERE p.principal_id = p_principal AND p.tenant_id = v_tenant AND p.app_id = v_app
    AND b.enabled AND f.enabled AND f.checked_at <= v_at AND v_at < f.valid_until
  FOR SHARE OF p, f, b;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_EXPIRED';
  END IF;
  SELECT r.directory_revision INTO v_revision
  FROM content_intake.shop_directory_revisions r
  WHERE r.tenant_id = v_tenant AND r.app_id = v_app;
  IF NOT FOUND THEN
    v_revision := 0;
  END IF;
  -- One jsonb value, not a temporary table: a pooled session must be able to call
  -- this function again without reusing a dropped relation's cached plan.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'shopId', q.shop_id,
           'displayName', q.display_name,
           'displayVersion', q.display_version,
           'shopDeadline', q.shop_deadline
         ) ORDER BY q.shop_id COLLATE "C"), '[]'::jsonb)
    INTO v_visible
  FROM (
    SELECT s.shop_id, d.display_name, c.display_version,
           min(content_intake.authorization_deadline(p_principal, 'query', s.scope_id, src.source_id, v_at)) AS shop_deadline
    FROM content_intake.scopes s
    JOIN content_intake.sources src ON src.scope_id = s.scope_id AND src.mode = 'v2-preview'
    LEFT JOIN content_intake.shop_display_current c
      ON c.tenant_id = s.tenant_id AND c.app_id = s.app_id AND c.shop_id = s.shop_id
    LEFT JOIN content_intake.shop_displays d
      ON d.tenant_id = c.tenant_id AND d.app_id = c.app_id AND d.shop_id = c.shop_id
     AND d.display_version = c.display_version
    WHERE s.tenant_id = v_tenant AND s.app_id = v_app AND s.shop_id IS NOT NULL
      AND content_intake.authorization_deadline(p_principal, 'query', s.scope_id, src.source_id, v_at) IS NOT NULL
    GROUP BY s.shop_id, d.display_name, c.display_version
  ) q;
  IF (SELECT count(DISTINCT item->>'shopId') FROM jsonb_array_elements(v_visible) item)
     IS DISTINCT FROM jsonb_array_length(v_visible) THEN
    RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'SHOP_DIRECTORY_DUPLICATE';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_visible) item
    WHERE item->>'displayName' IS NULL OR item->>'displayVersion' IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DISPLAY_MISSING';
  END IF;
  SELECT pg_catalog.encode(public.digest(pg_catalog.convert_to(
           coalesce(string_agg(item->>'shopId' || ':' || (item->>'displayVersion'), ','
                    ORDER BY item->>'shopId' COLLATE "C"), ''),
           'UTF8'), 'sha256'), 'hex'),
         min((item->>'shopDeadline')::timestamptz),
         count(*)
    INTO v_digest, v_deadline, v_count
  FROM jsonb_array_elements(v_visible) item;
  IF v_count = 0 THEN
    v_deadline := v_fact_until;
  ELSE
    v_deadline := least(v_fact_until, v_deadline);
  END IF;
  v_deadline := least(v_deadline,p_outer_deadline);
  v_deadline := date_trunc('milliseconds', v_deadline);
  v_deadline_us := (extract(epoch FROM v_deadline) * 1000000)::bigint;
  IF p_cursor IS NOT NULL THEN
    v_match := regexp_match(p_cursor, '^sd2\.([0-9]+)\.([0-9]+)\.([0-9]+)\.([0-9a-f]{64})\.([0-9]+)\.([0-9]+)\.([0-9]+)\.([A-Za-z0-9][A-Za-z0-9._:-]{0,127})\.([0-9a-f]{64})$');
    IF v_match IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
    END IF;
    BEGIN
      v_cursor_facts := v_match[1]::bigint;
      v_cursor_revocation := v_match[2]::bigint;
      v_cursor_revision := v_match[3]::bigint;
      v_cursor_digest := v_match[4];
      v_cursor_deadline_us := v_match[5]::bigint;
      v_cursor_ord := v_match[6]::bigint;
      v_cursor_limit := v_match[7]::integer;
      v_cursor_shop := v_match[8];
      v_cursor_signature := v_match[9];
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
    END;
    v_payload := left(p_cursor, length(p_cursor) - 65);
    v_signature := encode(public.hmac(convert_to(jsonb_build_array(p_principal, v_tenant, v_app, p_session_hash, v_payload)::text, 'UTF8'), decode(p_cursor_signing_key, 'hex'), 'sha256'), 'hex');
    IF v_cursor_signature IS DISTINCT FROM v_signature OR v_cursor_limit IS DISTINCT FROM v_limit THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
    END IF;
    IF v_cursor_facts IS DISTINCT FROM v_facts OR v_cursor_revocation IS DISTINCT FROM v_revocation THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CHANGED';
    END IF;
    IF v_cursor_revision IS DISTINCT FROM v_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CHANGED';
    END IF;
    IF (extract(epoch FROM v_at) * 1000000)::bigint >= v_cursor_deadline_us THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_EXPIRED';
    END IF;
    IF v_deadline_us < v_cursor_deadline_us OR v_cursor_digest IS DISTINCT FROM v_digest THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CHANGED';
    END IF;
    BEGIN
      v_boundary := v_visible -> ((v_cursor_ord - 1)::integer) ->> 'shopId';
    EXCEPTION WHEN numeric_value_out_of_range THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
    END;
    IF v_boundary IS NULL OR v_boundary IS DISTINCT FROM v_cursor_shop OR v_cursor_ord < 1 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
    END IF;
    -- Renewal must not extend the original pagination lifetime.
    v_deadline_us := v_cursor_deadline_us;
    v_deadline := to_timestamp(v_deadline_us / 1000000.0);
  END IF;
  IF greatest(p_at, pg_catalog.clock_timestamp()) >= v_deadline THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_EXPIRED';
  END IF;
  v_after_count := v_count - coalesce(v_cursor_ord, 0);
  SELECT coalesce(jsonb_agg(page.item ORDER BY page.ord), '[]'::jsonb)
    INTO v_items
  FROM (
    SELECT t.ord, t.element - 'shopDeadline' AS item
    FROM jsonb_array_elements(v_visible) WITH ORDINALITY AS t(element, ord)
    WHERE t.ord > coalesce(v_cursor_ord, 0)
    ORDER BY t.ord
    LIMIT v_limit
  ) page;
  v_len := jsonb_array_length(v_items);
  v_next := NULL;
  IF v_after_count > v_limit THEN
    v_last := v_items -> (v_len - 1) ->> 'shopId';
    v_payload := 'sd2.' || v_facts::text || '.' || v_revocation::text || '.'
      || v_revision::text || '.' || v_digest || '.' || v_deadline_us::text || '.'
      || (coalesce(v_cursor_ord, 0) + v_len)::text || '.' || v_limit::text || '.' || v_last;
    v_signature := encode(public.hmac(convert_to(jsonb_build_array(p_principal, v_tenant, v_app, p_session_hash, v_payload)::text, 'UTF8'), decode(p_cursor_signing_key, 'hex'), 'sha256'), 'hex');
    v_next := v_payload || '.' || v_signature;
    IF octet_length(v_next) > 512 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_CURSOR';
    END IF;
  END IF;
  -- Page construction and HMAC can also consume the remaining lifetime.
  IF greatest(p_at, pg_catalog.clock_timestamp()) >= v_deadline THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SHOP_DIRECTORY_EXPIRED';
  END IF;
  RETURN jsonb_build_object(
    'items', v_items,
    'nextCursor', v_next,
    'validUntil', to_jsonb(date_trunc('milliseconds', v_deadline))
  );
END;
$$;

REVOKE ALL ON FUNCTION content_intake.shop_directory_steward_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.shop_display_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.shop_display_current_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.shop_directory_revision_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.upsert_shop_display(TEXT, TEXT, TEXT, TEXT, TEXT, BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.read_shop_directory(TEXT, TEXT, TIMESTAMPTZ, TEXT, INTEGER, TEXT, TIMESTAMPTZ) FROM PUBLIC;
REVOKE ALL ON TABLE content_intake.shop_directory_stewards FROM PUBLIC;
REVOKE ALL ON TABLE content_intake.shop_directory_revisions FROM PUBLIC;
REVOKE ALL ON TABLE content_intake.shop_displays FROM PUBLIC;
REVOKE ALL ON TABLE content_intake.shop_display_current FROM PUBLIC;

REVOKE ALL ON FUNCTION content_intake.valid_shop_display_name(TEXT) FROM PUBLIC;

-- Explicit governance bootstrap, not a job-derived tenant administrator.
-- Runtime roles cannot grant, edit or revoke these rows. The bootstrap owner is
-- a separate approval input; registrar operations still require director/manager.
CREATE TABLE content_intake.shop_directory_registrars (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  registrar_id content_intake.identifier NOT NULL,
  version content_intake.version NOT NULL,
  valid_from TIMESTAMPTZ NOT NULL CHECK (isfinite(valid_from)),
  valid_until TIMESTAMPTZ NOT NULL CHECK (isfinite(valid_until) AND valid_from < valid_until),
  revoked_at TIMESTAMPTZ CHECK (isfinite(revoked_at)),
  PRIMARY KEY (tenant_id,app_id,registrar_id),
  FOREIGN KEY (registrar_id,tenant_id,app_id) REFERENCES content_intake.principals(principal_id,tenant_id,app_id)
);
CREATE TABLE content_intake.shop_directory_steward_events (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  version content_intake.version NOT NULL,
  actor_id content_intake.identifier NOT NULL,
  actor_facts_version content_intake.version NOT NULL,
  registrar_version content_intake.version NOT NULL,
  prior_steward_id content_intake.identifier,
  steward_id content_intake.identifier,
  target_facts_version content_intake.version,
  valid_until TIMESTAMPTZ,
  operation_id content_intake.identifier NOT NULL,
  request_hash TEXT NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  reason TEXT NOT NULL CHECK (char_length(btrim(reason)) BETWEEN 1 AND 512),
  recorded_at TIMESTAMPTZ NOT NULL CHECK (isfinite(recorded_at)),
  result JSONB NOT NULL,
  PRIMARY KEY (tenant_id,app_id,version),
  UNIQUE (actor_id,operation_id)
);
-- Key material exists only on the current private state row, never in audit or
-- browser/API output. Rotation replaces it; revocation clears it. No real key is
-- created or bootstrapped by this draft. All application ACL remains revoked.
CREATE TABLE content_intake.shop_directory_keys (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  version content_intake.version NOT NULL,
  key_id content_intake.identifier,
  key_material TEXT,
  valid_from TIMESTAMPTZ,
  valid_until TIMESTAMPTZ,
  PRIMARY KEY (tenant_id,app_id),
  CHECK ((key_id IS NULL AND key_material IS NULL AND valid_from IS NULL AND valid_until IS NULL)
    OR (key_id IS NOT NULL AND key_material IS NOT NULL AND key_material ~ '^[0-9a-f]{64}$' AND valid_from IS NOT NULL
      AND isfinite(valid_from) AND valid_until IS NOT NULL AND isfinite(valid_until) AND valid_from < valid_until))
);
CREATE TABLE content_intake.shop_directory_key_events (
  tenant_id content_intake.identifier NOT NULL,
  app_id content_intake.identifier NOT NULL,
  version content_intake.version NOT NULL,
  key_id content_intake.identifier,
  operator_role TEXT NOT NULL,
  valid_until TIMESTAMPTZ,
  operation_id content_intake.identifier NOT NULL,
  request_hash TEXT NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  reason TEXT NOT NULL CHECK (char_length(btrim(reason)) BETWEEN 1 AND 512),
  recorded_at TIMESTAMPTZ NOT NULL CHECK (isfinite(recorded_at)),
  result JSONB NOT NULL,
  PRIMARY KEY (tenant_id,app_id,version),
  UNIQUE (tenant_id,app_id,operation_id)
);
CREATE FUNCTION content_intake.shop_directory_event_immutable() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_IMMUTABLE'; END;
$$;
CREATE TRIGGER shop_directory_steward_event_immutable BEFORE UPDATE OR DELETE ON content_intake.shop_directory_steward_events
FOR EACH ROW EXECUTE FUNCTION content_intake.shop_directory_event_immutable();
CREATE TRIGGER shop_directory_key_event_immutable BEFORE UPDATE OR DELETE ON content_intake.shop_directory_key_events
FOR EACH ROW EXECUTE FUNCTION content_intake.shop_directory_event_immutable();

-- Internal context consumer: lock order matches the product transaction owner.
-- No job/tenant/actor DTO is accepted in place of a real current product session.
CREATE FUNCTION content_intake.shop_directory_session_context(p_session_hash TEXT) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$
DECLARE v RECORD; v_roles TEXT[];
BEGIN
  PERFORM backend_review.lock_content();
  SELECT p.principal_id,p.tenant_id,p.app_id,p.current_facts_version,p.revocation_generation,
    least(s.expires_at,f.valid_until) AS valid_until,f.department_ids,f.job_id
    INTO v
  FROM backend_identity.sessions s JOIN backend_identity.subject_bindings b USING(binding_id)
  JOIN content_intake.principals p ON p.user_id=b.user_id
  JOIN content_intake.principal_facts f ON f.principal_id=p.principal_id AND f.facts_version=p.current_facts_version
  WHERE s.token_hash=p_session_hash AND s.revoked_at IS NULL AND b.enabled AND f.enabled
    AND s.issued_at <= clock_timestamp() AND clock_timestamp()<s.expires_at
    AND f.checked_at<=clock_timestamp() AND clock_timestamp()<f.valid_until
  FOR SHARE OF s,b,p,f;
  IF NOT FOUND OR clock_timestamp()>=v.valid_until THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_SESSION';
  END IF;
  SELECT array_agg(DISTINCT r.role::text) INTO v_roles FROM content_intake.role_rules r
    WHERE r.tenant_id=v.tenant_id AND r.app_id=v.app_id AND r.department_id=ANY(v.department_ids) AND r.job_id=v.job_id;
  RETURN jsonb_build_object('principal',v.principal_id,'tenant',v.tenant_id,'app',v.app_id,
    'factsVersion',v.current_facts_version,'generation',v.revocation_generation,
    'role',CASE WHEN cardinality(v_roles)=1 THEN v_roles[1] ELSE NULL END,
    'sessionHash',p_session_hash,'validUntil',v.valid_until);
END;
$$;

CREATE FUNCTION content_intake.manage_shop_directory_steward(p_session_hash TEXT,p_target TEXT,
  p_expected_version BIGINT,p_target_facts BIGINT,p_valid_until TIMESTAMPTZ,p_reason TEXT,p_operation TEXT) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c JSONB; r RECORD; old content_intake.shop_directory_stewards; prior RECORD; target RECORD;
  digest TEXT; answer JSONB; version BIGINT; deadline TIMESTAMPTZ;
BEGIN
  c:=content_intake.shop_directory_session_context(p_session_hash);
  IF c->>'role' IS NULL OR c->>'role' NOT IN ('director','manager') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_REGISTRAR_REQUIRED';
  END IF;
  SELECT * INTO r FROM content_intake.shop_directory_registrars
   WHERE tenant_id=c->>'tenant' AND app_id=c->>'app' AND registrar_id=c->>'principal'
     AND revoked_at IS NULL AND valid_from<=clock_timestamp() AND clock_timestamp()<valid_until FOR SHARE;
  IF NOT FOUND OR clock_timestamp()>=r.valid_until THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_REGISTRAR_REQUIRED';
  END IF;
  deadline:=least((c->>'validUntil')::timestamptz,r.valid_until);
  IF p_expected_version IS NULL OR p_expected_version<0 OR p_operation IS NULL
     OR p_operation !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     OR p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 1 AND 512 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_INVALID';
  END IF;
  digest:=encode(public.digest(convert_to(jsonb_build_array(p_target,p_expected_version,p_target_facts,extract(epoch FROM p_valid_until),p_reason)::text,'UTF8'),'sha256'),'hex');
  SELECT * INTO prior FROM content_intake.shop_directory_steward_events WHERE actor_id=c->>'principal' AND operation_id=p_operation;
  IF FOUND THEN
    IF prior.request_hash<>digest THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CONFLICT'; END IF;
    RETURN jsonb_build_object('value',prior.result,'context',c,'deadline',deadline,'kind','replay','registrarVersion',r.version);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended((c->>'tenant')||':'||(c->>'app'),0));
  SELECT * INTO old FROM content_intake.shop_directory_stewards WHERE tenant_id=c->>'tenant' AND app_id=c->>'app' FOR UPDATE;
  IF coalesce(old.version,0)<>p_expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CONFLICT';
  END IF;
  IF p_target IS NULL THEN
    IF old.version IS NULL OR NOT old.active OR p_target_facts IS NOT NULL OR p_valid_until IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_INVALID';
    END IF;
  ELSE
    SELECT p.principal_id,p.current_facts_version,f.valid_until INTO target
      FROM content_intake.principals p JOIN content_intake.principal_facts f ON f.principal_id=p.principal_id AND f.facts_version=p.current_facts_version
      JOIN backend_identity.subject_bindings b ON b.user_id=p.user_id
      JOIN LATERAL (SELECT count(DISTINCT rr.role) AS n,min(rr.role) AS role FROM content_intake.role_rules rr
        WHERE rr.tenant_id=p.tenant_id AND rr.app_id=p.app_id AND rr.department_id=ANY(f.department_ids) AND rr.job_id=f.job_id) roles
        ON roles.n=1 AND roles.role IN ('director','manager')
      WHERE p.principal_id=p_target AND p.tenant_id=c->>'tenant' AND p.app_id=c->>'app'
        AND p.current_facts_version=p_target_facts AND b.enabled AND f.enabled
        AND f.checked_at<=clock_timestamp() AND clock_timestamp()<f.valid_until FOR SHARE OF p,f,b;
    IF NOT FOUND OR p_valid_until IS NULL OR NOT isfinite(p_valid_until) OR clock_timestamp()>=p_valid_until OR p_valid_until>r.valid_until THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_STEWARD_REQUIRED';
    END IF;
    deadline:=least(deadline,target.valid_until);
  END IF;
  version:=coalesce(old.version,0)+1;
  answer:=jsonb_build_object('version',version,'stewardId',p_target,'active',p_target IS NOT NULL,'validUntil',p_valid_until);
  INSERT INTO content_intake.shop_directory_steward_events VALUES(c->>'tenant',c->>'app',version,c->>'principal',
    (c->>'factsVersion')::bigint,r.version,old.steward_id,p_target,p_target_facts,p_valid_until,p_operation,digest,p_reason,clock_timestamp(),answer);
  PERFORM set_config('content_intake.directory_steward_write','writing',true);
  INSERT INTO content_intake.shop_directory_stewards(tenant_id,app_id,steward_id,registered_at,version,active,valid_until)
    VALUES(c->>'tenant',c->>'app',p_target,clock_timestamp(),version,p_target IS NOT NULL,p_valid_until)
    ON CONFLICT(tenant_id,app_id) DO UPDATE SET steward_id=EXCLUDED.steward_id,registered_at=EXCLUDED.registered_at,
      version=EXCLUDED.version,active=EXCLUDED.active,valid_until=EXCLUDED.valid_until;
  PERFORM set_config('content_intake.directory_steward_write','',true);
  IF clock_timestamp()>=deadline THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_EXPIRED'; END IF;
  RETURN jsonb_build_object('value',answer,'context',c,'deadline',deadline,'kind','manage','registrarVersion',r.version,
    'stewardVersion',version,'target',p_target,'targetFacts',p_target_facts);
END;
$$;

-- Infrastructure-only operator entry. Granting this entry is not a business-role
-- decision and never follows from director/manager. No runtime application ACL.
CREATE FUNCTION content_intake.rotate_shop_directory_key(p_tenant TEXT,p_app TEXT,p_key_id TEXT,p_material TEXT,
  p_valid_until TIMESTAMPTZ,p_expected_version BIGINT,p_reason TEXT,p_operation TEXT) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE old content_intake.shop_directory_keys; prior RECORD; digest TEXT; version BIGINT; answer JSONB;
BEGIN
  PERFORM backend_review.lock_content();
  IF p_tenant IS NULL OR p_app IS NULL OR p_expected_version IS NULL OR p_expected_version<0
    OR p_tenant !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' OR p_app !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    OR p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 1 AND 512
    OR p_operation IS NULL OR p_operation !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_INVALID';
  END IF;
  digest:=encode(public.digest(convert_to(jsonb_build_array(p_key_id,p_material,extract(epoch FROM p_valid_until),p_expected_version,p_reason)::text,'UTF8'),'sha256'),'hex');
  SELECT * INTO prior FROM content_intake.shop_directory_key_events WHERE tenant_id=p_tenant AND app_id=p_app AND operation_id=p_operation;
  IF FOUND THEN
    IF prior.request_hash<>digest THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CONFLICT'; END IF;
    RETURN prior.result;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant||':'||p_app,0));
  SELECT * INTO old FROM content_intake.shop_directory_keys WHERE tenant_id=p_tenant AND app_id=p_app FOR UPDATE;
  IF coalesce(old.version,0)<>p_expected_version THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CONFLICT'; END IF;
  IF p_key_id IS NULL THEN
    IF old.version IS NULL OR old.key_id IS NULL OR p_material IS NOT NULL OR p_valid_until IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_INVALID';
    END IF;
  ELSIF p_key_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' OR p_material IS NULL OR p_material !~ '^[0-9a-f]{64}$'
    OR p_valid_until IS NULL OR NOT isfinite(p_valid_until) OR clock_timestamp()>=p_valid_until
    OR EXISTS(SELECT 1 FROM content_intake.shop_directory_key_events WHERE tenant_id=p_tenant AND app_id=p_app AND key_id=p_key_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_INVALID';
  END IF;
  version:=coalesce(old.version,0)+1;
  answer:=jsonb_build_object('version',version,'keyId',p_key_id,'active',p_key_id IS NOT NULL,'validUntil',p_valid_until);
  INSERT INTO content_intake.shop_directory_key_events VALUES(p_tenant,p_app,version,p_key_id,
    coalesce(nullif(current_setting('role',true),'none'),session_user),p_valid_until,p_operation,digest,p_reason,clock_timestamp(),answer);
  INSERT INTO content_intake.shop_directory_keys VALUES(p_tenant,p_app,version,p_key_id,p_material,
    CASE WHEN p_key_id IS NOT NULL THEN clock_timestamp() ELSE NULL END,p_valid_until)
    ON CONFLICT(tenant_id,app_id) DO UPDATE SET version=EXCLUDED.version,key_id=EXCLUDED.key_id,key_material=EXCLUDED.key_material,
      valid_from=EXCLUDED.valid_from,valid_until=EXCLUDED.valid_until;
  IF p_key_id IS NOT NULL AND clock_timestamp()>=p_valid_until THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_EXPIRED';
  END IF;
  RETURN answer;
END;
$$;

-- A key version is part of the cryptographic domain. Reusing the same raw
-- material under a new id/version still invalidates every old cursor.
CREATE FUNCTION content_intake.shop_directory_signing_key(k content_intake.shop_directory_keys) RETURNS TEXT
LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $$
  SELECT encode(public.hmac(convert_to(jsonb_build_array(k.tenant_id,k.app_id,k.key_id,k.version)::text,'UTF8'),
    decode(k.key_material,'hex'),'sha256'),'hex')
$$;
CREATE FUNCTION content_intake.prepare_shop_directory_read(p_session_hash TEXT,p_cursor TEXT,p_limit INTEGER) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c JSONB; k content_intake.shop_directory_keys; answer JSONB; deadline TIMESTAMPTZ;
BEGIN
  c:=content_intake.shop_directory_session_context(p_session_hash);
  SELECT * INTO k FROM content_intake.shop_directory_keys WHERE tenant_id=c->>'tenant' AND app_id=c->>'app' FOR SHARE;
  IF NOT FOUND OR k.key_id IS NULL OR k.valid_from>clock_timestamp() OR clock_timestamp()>=k.valid_until THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_UNAVAILABLE';
  END IF;
  deadline:=least((c->>'validUntil')::timestamptz,k.valid_until);
  answer:=content_intake.read_shop_directory(c->>'principal',p_session_hash,clock_timestamp(),p_cursor,p_limit,content_intake.shop_directory_signing_key(k),deadline);
  RETURN jsonb_build_object('value',answer,'context',c,'deadline',answer->'validUntil','kind','read',
    'keyVersion',k.version,'cursor',p_cursor,'limit',p_limit);
END;
$$;
CREATE FUNCTION content_intake.prepare_shop_directory_write(p_session_hash TEXT,p_shop TEXT,p_name TEXT,p_expected_revision BIGINT) RETURNS JSONB
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c JSONB; s content_intake.shop_directory_stewards; answer JSONB;
BEGIN
  c:=content_intake.shop_directory_session_context(p_session_hash);
  IF c->>'role' IS NULL OR c->>'role' NOT IN ('director','manager') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_STEWARD_REQUIRED';
  END IF;
  SELECT * INTO s FROM content_intake.shop_directory_stewards WHERE tenant_id=c->>'tenant' AND app_id=c->>'app'
    AND steward_id=c->>'principal' AND active AND clock_timestamp()<valid_until FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_STEWARD_REQUIRED'; END IF;
  answer:=content_intake.upsert_shop_display(c->>'principal',c->>'tenant',c->>'app',p_shop,p_name,p_expected_revision);
  RETURN jsonb_build_object('value',answer,'context',c,'deadline',least((c->>'validUntil')::timestamptz,s.valid_until),
    'kind','write','stewardVersion',s.version);
END;
$$;
-- The unique transaction owner calls this after all work and before COMMIT. It
-- re-reads current authority and uses DB time; an earlier successful prepare is
-- not a commit permit. No output envelope or key is released to the caller.
CREATE FUNCTION content_intake.finish_shop_directory_transaction(p_envelope JSONB) RETURNS VOID
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c JSONB; now_context JSONB; s RECORD; r RECORD; k content_intake.shop_directory_keys; current_value JSONB; deadline TIMESTAMPTZ;
BEGIN
  c:=p_envelope->'context';
  IF p_envelope IS NULL OR jsonb_typeof(p_envelope)<>'object' OR p_envelope->>'kind' IS NULL
    OR p_envelope->>'kind' NOT IN ('read','write','manage','replay') OR c IS NULL OR p_envelope->>'deadline' IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DISPLAY_INVALID';
  END IF;
  now_context:=content_intake.shop_directory_session_context(c->>'sessionHash');
  IF (now_context->>'principal',now_context->>'tenant',now_context->>'app',now_context->>'factsVersion',now_context->>'generation')
    IS DISTINCT FROM(c->>'principal',c->>'tenant',c->>'app',c->>'factsVersion',c->>'generation') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CHANGED';
  END IF;
  deadline:=least((p_envelope->>'deadline')::timestamptz,(now_context->>'validUntil')::timestamptz);
  IF p_envelope->>'kind'='read' THEN
    SELECT * INTO k FROM content_intake.shop_directory_keys WHERE tenant_id=c->>'tenant' AND app_id=c->>'app' FOR SHARE;
    IF NOT FOUND OR k.key_id IS NULL OR k.version<>(p_envelope->>'keyVersion')::bigint OR clock_timestamp()>=k.valid_until THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_UNAVAILABLE';
    END IF;
    deadline:=least(deadline,k.valid_until);
    current_value:=content_intake.read_shop_directory(c->>'principal',c->>'sessionHash',clock_timestamp(),
      p_envelope->>'cursor',(p_envelope->>'limit')::integer,content_intake.shop_directory_signing_key(k),deadline);
    IF current_value IS DISTINCT FROM p_envelope->'value' THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CHANGED';
    END IF;
  ELSE
    IF p_envelope->>'kind' IN ('manage','replay') THEN
      SELECT * INTO r FROM content_intake.shop_directory_registrars WHERE tenant_id=c->>'tenant' AND app_id=c->>'app'
        AND registrar_id=c->>'principal' AND version=(p_envelope->>'registrarVersion')::bigint
        AND revoked_at IS NULL AND valid_from<=clock_timestamp() AND clock_timestamp()<valid_until FOR SHARE;
      IF NOT FOUND OR now_context->>'role' IS NULL OR now_context->>'role' NOT IN ('director','manager') THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_REGISTRAR_REQUIRED';
      END IF;
      deadline:=least(deadline,r.valid_until);
    END IF;
    IF p_envelope->>'kind'<>'replay' THEN
      SELECT * INTO s FROM content_intake.shop_directory_stewards WHERE tenant_id=c->>'tenant' AND app_id=c->>'app'
        AND version=(p_envelope->>'stewardVersion')::bigint FOR SHARE;
      IF NOT FOUND OR (p_envelope->>'kind'='write' AND (NOT s.active OR s.steward_id<>c->>'principal'
          OR now_context->>'role' IS NULL OR now_context->>'role' NOT IN ('director','manager'))) THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CHANGED';
      END IF;
      IF s.active THEN deadline:=least(deadline,s.valid_until); END IF;
    END IF;
    IF p_envelope->>'target' IS NOT NULL THEN
      PERFORM 1 FROM content_intake.principals p JOIN content_intake.principal_facts f ON f.principal_id=p.principal_id AND f.facts_version=p.current_facts_version
        JOIN backend_identity.subject_bindings b ON b.user_id=p.user_id
        JOIN LATERAL (SELECT count(DISTINCT rr.role) AS n,min(rr.role) AS role FROM content_intake.role_rules rr
          WHERE rr.tenant_id=p.tenant_id AND rr.app_id=p.app_id AND rr.department_id=ANY(f.department_ids) AND rr.job_id=f.job_id) roles
          ON roles.n=1 AND roles.role IN ('director','manager')
        WHERE p.principal_id=p_envelope->>'target' AND p.current_facts_version=(p_envelope->>'targetFacts')::bigint
          AND b.enabled AND f.enabled AND f.checked_at<=clock_timestamp() AND clock_timestamp()<f.valid_until;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_CHANGED'; END IF;
    END IF;
  END IF;
  IF NOT isfinite(deadline) OR clock_timestamp()>=deadline THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SHOP_DIRECTORY_EXPIRED';
  END IF;
END;
$$;

REVOKE ALL ON TABLE content_intake.shop_directory_registrars,content_intake.shop_directory_steward_events,
  content_intake.shop_directory_keys,content_intake.shop_directory_key_events FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.shop_directory_event_immutable() FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.shop_directory_session_context(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.manage_shop_directory_steward(TEXT,TEXT,BIGINT,BIGINT,TIMESTAMPTZ,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.rotate_shop_directory_key(TEXT,TEXT,TEXT,TEXT,TIMESTAMPTZ,BIGINT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.prepare_shop_directory_read(TEXT,TEXT,INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.prepare_shop_directory_write(TEXT,TEXT,TEXT,BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION content_intake.finish_shop_directory_transaction(JSONB) FROM PUBLIC;

REVOKE ALL ON FUNCTION content_intake.shop_directory_signing_key(content_intake.shop_directory_keys) FROM PUBLIC;
-- END INTAKE SHOP DIRECTORY

-- BEGIN INTAKE RUNTIME DIRECTORY ACL 49b4555f80cfe8d7302c67d081cc49a915949b613acda564dcd408a6232c67fa
-- Trusted registered organization service; append-only histories and pointer
-- transitions remain guarded. No bindings/principals/role/grant creation in the
-- identity or content authority domains is granted.
GRANT USAGE ON SCHEMA intake_organization TO intake_org_writer;
GRANT SELECT,INSERT ON intake_organization.bindings,intake_organization.current_bindings,intake_organization.observations TO intake_org_writer;
GRANT UPDATE(binding_version,open_id) ON intake_organization.current_bindings TO intake_org_writer;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA intake_organization TO intake_org_writer;

-- Directory owns only its own state and keys; it does not borrow publication
-- table writes from intake_runtime_fn_owner. Public low-level EXECUTE stays off.
GRANT USAGE ON SCHEMA content_intake,backend_identity,backend_review,public TO intake_directory_fn_owner;
GRANT USAGE ON SCHEMA content_intake TO intake_directory_key_operator;
GRANT SELECT ON backend_identity.sessions,backend_identity.subject_bindings,
  content_intake.principals,content_intake.principal_facts,content_intake.role_rules,
  content_intake.grants,content_intake.scopes,content_intake.sources TO intake_directory_fn_owner;
GRANT UPDATE(token_hash) ON backend_identity.sessions TO intake_directory_fn_owner;
GRANT UPDATE(user_id) ON backend_identity.subject_bindings TO intake_directory_fn_owner;
GRANT UPDATE(principal_id) ON content_intake.principals,content_intake.principal_facts TO intake_directory_fn_owner;
GRANT EXECUTE ON FUNCTION backend_review.lock_content(),public.digest(bytea,text),public.hmac(bytea,bytea,text),
  content_intake.authorization_deadline(text,text,text,text,timestamptz) TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_directory_stewards OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_directory_revisions OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_displays OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_display_current OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_directory_registrars OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_directory_steward_events OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_directory_keys OWNER TO intake_directory_fn_owner;
ALTER TABLE content_intake.shop_directory_key_events OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.valid_shop_display_name(text) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_directory_steward_guard() OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_display_guard() OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_display_current_guard() OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_directory_revision_guard() OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.upsert_shop_display(text,text,text,text,text,bigint) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.read_shop_directory(text,text,timestamptz,text,integer,text,timestamptz) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_directory_event_immutable() OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_directory_session_context(text) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.manage_shop_directory_steward(text,text,bigint,bigint,timestamptz,text,text) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.rotate_shop_directory_key(text,text,text,text,timestamptz,bigint,text,text) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.shop_directory_signing_key(content_intake.shop_directory_keys) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.prepare_shop_directory_read(text,text,integer) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.prepare_shop_directory_write(text,text,text,bigint) OWNER TO intake_directory_fn_owner;
ALTER FUNCTION content_intake.finish_shop_directory_transaction(jsonb) OWNER TO intake_directory_fn_owner;
GRANT EXECUTE ON FUNCTION content_intake.prepare_shop_directory_read(text,text,integer),content_intake.finish_shop_directory_transaction(jsonb) TO intake_usage;
GRANT EXECUTE ON FUNCTION content_intake.prepare_shop_directory_write(text,text,text,bigint),content_intake.manage_shop_directory_steward(text,text,bigint,bigint,timestamptz,text,text),content_intake.finish_shop_directory_transaction(jsonb) TO intake_business;
GRANT EXECUTE ON FUNCTION content_intake.rotate_shop_directory_key(text,text,text,text,timestamptz,bigint,text,text) TO intake_directory_key_operator;
-- Core directory consumers can run independently of product-only publication
-- overlays. These minimum grants do not activate the business upload service.
GRANT USAGE ON SCHEMA content_intake,backend_review TO intake_usage,intake_business,intake_org_writer;
