-- BEGIN SOP MEDIA CONTRACT 1d009c6820abaa749759f63ae5c9e190397acc851bd9ce9e7042233117d9e988
-- SOP media is an additive candidate only. The real storage provider, bucket, key and secret are undecided.
BEGIN;
CREATE TABLE content_intake.sop_media_objects (
  media_object_id content_intake.identifier PRIMARY KEY,
  source_id content_intake.identifier NOT NULL REFERENCES content_intake.sources,
  actor_id content_intake.identifier NOT NULL REFERENCES content_intake.principals,
  sha256 content_intake.sha256 NOT NULL,
  bytes BIGINT NOT NULL CHECK (bytes BETWEEN 1 AND 5242880),
  mime TEXT NOT NULL CHECK (mime IN ('image/png','image/jpeg','image/gif')),
  state TEXT NOT NULL DEFAULT 'staged' CHECK (state IN ('staged','adopted','released','discarded')),
  created_at TIMESTAMPTZ NOT NULL CHECK (isfinite(created_at)),
  adopted_at TIMESTAMPTZ,
  discarded_at TIMESTAMPTZ,
  UNIQUE (source_id,sha256,bytes,mime),
  UNIQUE (media_object_id,source_id,sha256,bytes,mime),
  CHECK ((state='staged' AND adopted_at IS NULL AND discarded_at IS NULL)
    OR (state IN ('adopted','released') AND adopted_at IS NOT NULL AND discarded_at IS NULL)
    OR (state='discarded' AND adopted_at IS NULL AND discarded_at IS NOT NULL)),
  CHECK (adopted_at IS NULL OR adopted_at>=created_at),
  CHECK (discarded_at IS NULL OR discarded_at>=created_at)
);
CREATE TABLE content_intake.sop_candidate_media (
  candidate_id content_intake.identifier NOT NULL,
  candidate_version content_intake.version NOT NULL,
  source_id content_intake.identifier NOT NULL,
  media_object_id content_intake.identifier NOT NULL,
  sheet_name TEXT NOT NULL CHECK (sheet_name IN ('过敏流程SOP','少错破SOP','品质售后SOP','税收相关规则','品牌对接资源汇总','长痘痘SOP')),
  row_number INTEGER NOT NULL CHECK (row_number BETWEEN 1 AND 5000),
  column_number INTEGER NOT NULL CHECK (column_number BETWEEN 1 AND 32),
  row_id TEXT NOT NULL CHECK (row_id = 'sop:' || sheet_name || ':' || row_number::TEXT),
  ordinal INTEGER NOT NULL CHECK (ordinal BETWEEN 1 AND 100),
  sha256 content_intake.sha256 NOT NULL,
  mime TEXT NOT NULL CHECK (mime IN ('image/png','image/jpeg','image/gif')),
  bytes BIGINT NOT NULL CHECK (bytes BETWEEN 1 AND 5242880),
  PRIMARY KEY (candidate_id,candidate_version,media_object_id,ordinal),
  UNIQUE (candidate_id,candidate_version,source_id,sheet_name,row_number,column_number,ordinal),
  UNIQUE (candidate_id,candidate_version,source_id,media_object_id,sheet_name,row_number,column_number,row_id,ordinal,sha256,mime,bytes),
  FOREIGN KEY (candidate_id,candidate_version,source_id) REFERENCES content_intake.candidate_versions(candidate_id,version,source_id),
  FOREIGN KEY (media_object_id,source_id,sha256,bytes,mime) REFERENCES content_intake.sop_media_objects(media_object_id,source_id,sha256,bytes,mime)
);
CREATE TABLE content_intake.sop_release_media (
  release_id TEXT NOT NULL REFERENCES public.content_releases,
  candidate_id content_intake.identifier NOT NULL,
  candidate_version content_intake.version NOT NULL,
  source_id content_intake.identifier NOT NULL,
  media_object_id content_intake.identifier NOT NULL,
  sheet_name TEXT NOT NULL CHECK (sheet_name IN ('过敏流程SOP','少错破SOP','品质售后SOP','税收相关规则','品牌对接资源汇总','长痘痘SOP')),
  row_number INTEGER NOT NULL CHECK (row_number BETWEEN 1 AND 5000),
  column_number INTEGER NOT NULL CHECK (column_number BETWEEN 1 AND 32),
  row_id TEXT NOT NULL CHECK (row_id = 'sop:' || sheet_name || ':' || row_number::TEXT),
  ordinal INTEGER NOT NULL CHECK (ordinal BETWEEN 1 AND 100),
  sha256 content_intake.sha256 NOT NULL,
  mime TEXT NOT NULL CHECK (mime IN ('image/png','image/jpeg','image/gif')),
  bytes BIGINT NOT NULL CHECK (bytes BETWEEN 1 AND 5242880),
  PRIMARY KEY (release_id,media_object_id,ordinal),
  FOREIGN KEY (candidate_id,candidate_version,source_id,media_object_id,sheet_name,row_number,column_number,row_id,ordinal,sha256,mime,bytes)
    REFERENCES content_intake.sop_candidate_media(candidate_id,candidate_version,source_id,media_object_id,sheet_name,row_number,column_number,row_id,ordinal,sha256,mime,bytes)
);
ALTER TABLE content_intake.sop_media_objects OWNER TO intake_runtime_fn_owner;
ALTER TABLE content_intake.sop_candidate_media OWNER TO intake_runtime_fn_owner;
ALTER TABLE content_intake.sop_release_media OWNER TO intake_runtime_fn_owner;
REVOKE ALL ON TABLE content_intake.sop_media_objects FROM PUBLIC;
REVOKE ALL ON TABLE content_intake.sop_candidate_media FROM PUBLIC;
REVOKE ALL ON TABLE content_intake.sop_release_media FROM PUBLIC;
COMMENT ON TABLE content_intake.sop_media_objects IS 'SOP 图片对象候选；真实对象存储未定，预览不暴露永久 URL；历史永久保留，未使用内容允许人工删除。';
COMMENT ON TABLE content_intake.sop_candidate_media IS 'SOP 图片按工作表、行号和列号绑定；每行必须另有文字答案，同一行可有多图。';
COMMENT ON TABLE content_intake.sop_release_media IS 'SOP 发布单元的不可变图片关系；已发布或正在使用的内容不得删除，不设自动到期。';
COMMIT;

-- END SOP MEDIA CONTRACT

-- EXACT schema 1.27 OVERLAY (not a second cumulative baseline)
-- schema.v1.27 — approved additive successor; immutable schema.v1.26 follows unchanged
-- Not production. Does not replace the consumed OpenAPI 1.22.0 / schema 1.25 lock.
-- Adds scope domain sop, delete_unused_sop_row, and stage_sop_candidate_media.
-- No image bytes and no grants.
-- Executable statements are the product seeds menokin-sop-v1-27.sql and menokin-sop-stage.sql.
-- Product migrations 0037-0039 keep the ingested 1.26 successor sha. This overlay is not a separate ingested contract set.
-- predecessor_schema=schema.v1.26
-- predecessor_sha256=1c0a4e508ea0aab97d40abff4829ea5a0ce65882ad6a044187fc231872bbe39c
-- Approved schema.v1.27 additive delta. Immutable schema.v1.26 follows unchanged.
-- Adds the sop scope domain and unused-row deletion. No image bytes, no grants, no import.

DO $$
DECLARE constraint_name text;
BEGIN
  SELECT conname INTO constraint_name
  FROM pg_constraint
  WHERE conrelid = 'content_intake.scopes'::regclass
    AND contype = 'c'
    AND pg_get_constraintdef(oid) LIKE '%presale%product%';
  IF constraint_name IS NULL THEN
    RAISE EXCEPTION 'SOP_DOMAIN_CONSTRAINT_MISSING';
  END IF;
  EXECUTE format('ALTER TABLE content_intake.scopes DROP CONSTRAINT %I', constraint_name);
END $$;

ALTER TABLE content_intake.scopes ADD CONSTRAINT scopes_domain_check
  CHECK (domain IN ('presale','campaign','aftersale','product','sop'));

CREATE OR REPLACE FUNCTION content_intake.input_format_matches(p_template text,p_rule text,p_mapping text,p_structure text,p_mime text)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
  SELECT coalesce(
    (p_template='faq-p1.1' AND p_rule='intake-p1.1' AND p_mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      AND length(p_mapping) BETWEEN 1 AND 64 AND p_structure ~ '^[0-9a-f]{64}$')
    OR (p_template='faq-csv-v1' AND p_rule='intake-csv-v1' AND p_mapping='faq-csv-columns-v1'
      AND p_structure='daaa4126d63194f59949c2b6f464b108ed87a430090e4dfe36e255663ab59165' AND p_mime='text/csv')
    OR (p_template='sop-v1' AND p_rule='sop-not-imported' AND p_mapping='not-imported'
      AND p_structure='55db62261cb6eee8bb0327ffb4bf8eac1f30a667e6821f640431d4be47c3a925'
      AND p_mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'),
    false);
$$;

CREATE FUNCTION content_intake.delete_unused_sop_row(
  p_candidate_id content_intake.identifier,
  p_version content_intake.version,
  p_row_id text
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = content_intake, public, pg_temp
AS $$
DECLARE
  v_state text;
  v_source content_intake.identifier;
  v_media content_intake.identifier[];
BEGIN
  SELECT state, source_id INTO v_state, v_source
  FROM content_intake.candidate_versions
  WHERE candidate_id = p_candidate_id AND version = p_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'SOP_ROW_NOT_FOUND';
  END IF;
  IF v_state IN ('published','publishing') THEN
    RAISE EXCEPTION 'SOP_ROW_IN_USE';
  END IF;
  IF EXISTS (
    SELECT 1 FROM content_intake.sop_release_media
    WHERE candidate_id = p_candidate_id AND candidate_version = p_version AND row_id = p_row_id
  ) OR EXISTS (
    SELECT 1
    FROM content_intake.sop_candidate_media cm
    JOIN content_intake.sop_media_objects o ON o.media_object_id = cm.media_object_id
    WHERE cm.candidate_id = p_candidate_id AND cm.candidate_version = p_version AND cm.row_id = p_row_id
      AND (o.adopted_at IS NOT NULL OR o.state IN ('adopted','released'))
  ) THEN
    RAISE EXCEPTION 'SOP_ROW_IN_USE';
  END IF;
  SELECT coalesce(array_agg(media_object_id), ARRAY[]::content_intake.identifier[]) INTO v_media
  FROM content_intake.sop_candidate_media
  WHERE candidate_id = p_candidate_id AND candidate_version = p_version AND row_id = p_row_id;
  IF coalesce(cardinality(v_media), 0) = 0 THEN
    RAISE EXCEPTION 'SOP_ROW_NOT_FOUND';
  END IF;
  DELETE FROM content_intake.sop_candidate_media
  WHERE candidate_id = p_candidate_id AND candidate_version = p_version AND row_id = p_row_id;
  UPDATE content_intake.sop_media_objects o
  SET state = 'discarded', discarded_at = clock_timestamp()
  WHERE o.media_object_id = ANY(v_media)
    AND o.source_id = v_source
    AND o.adopted_at IS NULL
    AND o.state = 'staged'
    AND NOT EXISTS (SELECT 1 FROM content_intake.sop_candidate_media cm WHERE cm.media_object_id = o.media_object_id)
    AND NOT EXISTS (SELECT 1 FROM content_intake.sop_release_media rm WHERE rm.media_object_id = o.media_object_id);
END;
$$;

ALTER FUNCTION content_intake.delete_unused_sop_row(content_intake.identifier, content_intake.version, text)
  OWNER TO intake_runtime_fn_owner;
REVOKE ALL ON FUNCTION content_intake.delete_unused_sop_row(content_intake.identifier, content_intake.version, text) FROM PUBLIC;

